-- ============================================================
-- REFYN — QUESTION BANK SEED (part 1 of 4)
-- Source: Refyn_Question_Intake_8_fixed.xlsx, sheet "Question_Intake"
-- Rows 1-200 of 613
--
-- Run AFTER master_setup.sql + seed_taxonomy.sql, in the Supabase SQL Editor.
-- Idempotent: re-running skips rows already present (exam_id, external_id).
--
-- Transforms applied to the sheet data:
--   * question_type / correct_answer (MCQ) lowercased to match existing seeds
--   * calculation_level 'hard'->'high', 'easy'->'low' (CHECK allows low/medium/high)
--   * TITA rows get NULL options
--   * 39 solutions that were left mid-draft in the sheet were re-derived and
--     rewritten; answer keys were verified unchanged.
--   * subtopic resolved by concept_code; a row whose code is missing from
--     subtopics would be skipped -- the verification query at the end of
--     part 4 reports the final count.
-- ============================================================

INSERT INTO questions (
  exam_id, subtopic_id,
  external_id, year, slot, source, is_pyq,
  question_text, question_type,
  option_a, option_b, option_c, option_d,
  correct_answer, solution, alternate_solution,
  difficulty, calculation_level, logic_level,
  expected_time_seconds, common_mistakes
)
SELECT
  (SELECT id FROM exams WHERE slug = 'cat'), s.id,
  v.external_id, v.year, v.slot, v.source, v.is_pyq,
  v.question_text, v.question_type,
  v.option_a, v.option_b, v.option_c, v.option_d,
  v.correct_answer, v.solution, v.alternate_solution,
  v.difficulty, v.calculation_level, v.logic_level,
  v.expected_time_seconds, v.common_mistakes
FROM (VALUES
  ('CAT2023_QA_S1_17', 2023, 'Slot 1', 'CAT 2023 Official', TRUE, 'PERC_SUCCESSIVE', 'A shopkeeper marks up an item by 40% and then offers a discount of 20%. What is the net percentage change in price?', 'mcq', '10% increase', '12% increase', '15% increase', '8% increase', 'b', 'Net change = (100+40)(100-20)/100 - 100 = 112-100 = 12% increase', NULL, 6, 'medium', 'low', 75, 'Students often just subtract 40-20=20% instead of compounding'),
  ('CAT2024_QA_S1_01', 2024, 'Slot 1', 'CAT 2024 Slot 1', TRUE, 'GEO_COORD_CIRCLE', 'In the XY-plane, the area, in sq. units, of the region defined by the inequalities y ≥ x + 4 and −4 ≤ x² + y² + 4(x − y) ≤ 0 is', 'mcq', 'π', '2π', '4π', '3π', 'b', 'Rewrite x²+y²+4(x-y)≤0 as (x+2)²+(y-2)²≤8, and the lower bound as (x+2)²+(y-2)²≥4. This is an annulus between circles of radius 2 and 2√2 centred at (-2,2). The line y=x+4 passes exactly through the centre (-2,2), so it bisects the annulus. Annulus area = π(8-4)=4π; half of it = 2π.', NULL, 7, 'medium', 'high', 150, 'Forgetting to complete the square correctly, or not noticing the line passes through the centre and instead trying to integrate directly.'),
  ('CAT2024_QA_S1_02', 2024, 'Slot 1', 'CAT 2024 Slot 1', TRUE, 'ALG_INDICES', 'The sum of all real values of k for which (1/8)^k × (1/32768)^(1/3) = (1/8) × (1/32768)^(1/k), is', 'mcq', '4/3', '-4/3', '2/3', '-2/3', 'd', 'Express everything as powers of 2: 1/8=2^-3, 1/32768=2^-15. Equation becomes 2^(-3k-5)=2^(-3-15/k). Equate exponents: -3k-5=-3-15/k, multiply by k: -3k²-5k=-3k-15, i.e. 3k²+2k-15=0. Roots sum = -2/3.', NULL, 6, 'medium', 'medium', 120, 'Sign errors while equating exponents, or forgetting to use sum-of-roots formula directly instead of solving both roots.'),
  ('CAT2024_QA_S1_03', 2024, 'Slot 1', 'CAT 2024 Slot 1', TRUE, 'MOD_COUNT', 'The sum of all four-digit numbers that can be formed with the distinct non-zero digits a, b, c, and d, with each digit appearing exactly once in every number, is 153310 + n, where n is a single digit natural number. Then, the value of (a+b+c+d+n) is', 'tita', NULL, NULL, NULL, NULL, '31', 'Sum of all 4-digit numbers using 4 distinct digits (each used once) = 6666×(sum of digits), since each digit appears in each place value 6 times out of 24 permutations. Setting 6666S=153310+n and testing S=23 gives 6666×23=153318, so n=8. Then a+b+c+d+n = 23+8 = 31.', NULL, 6, 'medium', 'medium', 150, 'Using the wrong multiplier (should be 6×1111=6666, not 24×1111), or forgetting n must be a single digit natural number when checking S.'),
  ('CAT2024_QA_S1_04', 2024, 'Slot 1', 'CAT 2024 Slot 1', TRUE, 'TW_COMBINED', 'Renu would take 15 days working 4 hours per day to complete a certain task whereas Seema would take 8 days working 5 hours per day to complete the same task. They decide to work together to complete this task. Seema agrees to work for double the number of hours per day as Renu, while Renu agrees to work for double the number of days as Seema. If Renu works 2 hours per day, then the number of days Seema will work, is', 'tita', NULL, NULL, NULL, NULL, '6', 'Total work = 15×4=60 units (Renu''s rate) = 8×5=40 units (Seema''s rate); take LCM-based total work=120 units, so Renu''s rate=2 units/hr, Seema''s rate=3 units/hr. Renu works 2 hrs/day ⇒ Seema works 4 hrs/day. Let Seema work d days, Renu works 2d days. Total work done: Renu(2×2×2d)+Seema(3×4×d)=120 ⇒ 8d+12d=120 ⇒ d=6.', NULL, 6, 'high', 'medium', 150, 'Mixing up whose hours/days are doubled relative to whom, or using inconsistent total-work values between the two workers.'),
  ('CAT2024_QA_S1_05', 2024, 'Slot 1', 'CAT 2024 Slot 1', TRUE, 'NS_MISC', 'For any natural number n, let a_n be the largest integer not exceeding √n. Then the value of a1 + a2 + ⋯ + a50 is', 'tita', NULL, NULL, NULL, NULL, '217', 'a_n = k exactly when k² ≤ n ≤ (k+1)²−1, so the value k repeats (2k+1) times — except for the final block, which is cut off at n=50. Blocks: k=1 for n=1–3 (3 terms), k=2 for n=4–8 (5), k=3 for n=9–15 (7), k=4 for n=16–24 (9), k=5 for n=25–35 (11), k=6 for n=36–48 (13), and k=7 for n=49–50 (only 2 terms, since 8²=64 > 50). Sum = 1(3)+2(5)+3(7)+4(9)+5(11)+6(13)+7(2) = 3+10+21+36+55+78+14 = 217.', NULL, 5, 'medium', 'medium', 150, 'Miscounting how many n fall in each block [k²,(k+1)²-1], especially the last partial block up to n=50.'),
  ('CAT2024_QA_S1_06', 2024, 'Slot 1', 'CAT 2024 Slot 1', TRUE, 'GEO_SPHERE', 'The surface area of a closed rectangular box, which is inscribed in a sphere, is 846 sq cm, and the sum of the lengths of all its edges is 144 cm. The volume, in cubic cm, of the sphere is', 'mcq', '750π', '1125π√2', '1125π', '750π√2', 'b', 'Let edges be l,b,h. 2(lb+bh+hl)=846 and 4(l+b+h)=144 ⇒ l+b+h=36. Space diagonal² = l²+b²+h² = (l+b+h)²-2(lb+bh+hl) = 1296-846=450. Sphere diameter = diagonal = √450, radius²=450/4=112.5. Volume=(4/3)πr³, computing gives 1125π√2.', NULL, 8, 'high', 'medium', 180, 'Forgetting the box is inscribed in the sphere so the space diagonal equals the sphere''s diameter, or arithmetic slips computing r³.'),
  ('CAT2024_QA_S1_07', 2024, 'Slot 1', 'CAT 2024 Slot 1', TRUE, 'ALG_LOG', 'If x is a positive real number such that 4log₁₀x + 4log₁₀₀x + 8log₁₀₀₀x = 13, then the greatest integer not exceeding x, is', 'tita', NULL, NULL, NULL, NULL, '31', 'log₁₀₀x = (log₁₀x)/2 and log₁₀₀₀x=(log₁₀x)/3. Equation becomes 4t+2t+8t/3=13 where t=log₁₀x, i.e. (18t+8t)/3=13 ⇒ 26t/3=13⇒t=3/2. So x=10^1.5≈31.6, greatest integer not exceeding x is 31.', NULL, 7, 'medium', 'medium', 180, 'Incorrectly converting log base 100 and 1000 to base 10 (dividing by wrong factor).'),
  ('CAT2024_QA_S1_08', 2024, 'Slot 1', 'CAT 2024 Slot 1', TRUE, 'ALG_SURDS', 'If (a + b√n) is the positive square root of (29 − 12√5), where a and b are integers, and n is a natural number, then the maximum possible value of (a+b+n) is', 'mcq', '22', '4', '6', '18', 'c', '29-12√5 = 20+9-12√5 = (2√5)²+3²-2·3·2√5 = (3-2√5)², so a+b√n with a=3,b=-2,n=5 gives a+b+n=6 (taking the positive root convention that maximizes the sum).', NULL, 6, 'medium', 'medium', 120, 'Picking the wrong sign combination for a and b, or not checking which root is actually positive.'),
  ('CAT2024_QA_S1_09', 2024, 'Slot 1', 'CAT 2024 Slot 1', TRUE, 'ALG_LINEAR_WORD', 'A shop wants to sell a certain quantity (in kg) of grains. It sells half the quantity and an additional 3 kg of these grains to the first customer. Then, it sells half of the remaining quantity and an additional 3 kg of these grains to the second customer. Finally, when the shop sells half of the remaining quantity and an additional 3 kg of these grains to the third customer, there are no grains left. The initial quantity, in kg, of grains is', 'mcq', '50', '18', '42', '36', 'c', 'Work backwards from the empty shop. If a stage begins with R kg, the customer takes R/2 + 3, leaving R/2 − 3. Third customer: R/2 − 3 = 0 ⇒ R = 6. Second customer: R/2 − 3 = 6 ⇒ R = 18. First customer: R/2 − 3 = 18 ⇒ R = 42. So the shop started with 42 kg.', NULL, 5, 'medium', 'medium', 120, 'Working forward instead of backward and getting confused about which quantity ''remaining'' refers to at each stage.'),
  ('CAT2024_QA_S1_10', 2024, 'Slot 1', 'CAT 2024 Slot 1', TRUE, 'ALG_SPECIAL', 'Let x, y, and z be real numbers satisfying 4(x²+y²+z²)=a, 4(x−y−z)=3+a. Then a equals', 'mcq', '1', '3', '4', '1 1/3', 'b', 'From the second equation, express a=4(x-y-z)-3, substitute into first: 4(x²+y²+z²)=4(x-y-z)-3. Rearranging into sum-of-squares form (x-0.5)²+(y+0.5)²+(z+0.5)²=0 forces x=1/2,y=z=-1/2, giving a=3.', NULL, 6, 'medium', 'high', 150, 'Not recognizing the need to complete the square in three variables simultaneously to force each square to zero.'),
  ('CAT2024_QA_S1_11', 2024, 'Slot 1', 'CAT 2024 Slot 1', TRUE, 'SET_IEP', 'Consider two sets A={2,3,5,7,11,13} and B={1,8,27}. Let f be a function from A to B such that for every element b in B, there is at least one element a in A such that f(a)=b. Then, the total number of such functions f is', 'mcq', '665', '667', '537', '540', 'd', 'This counts onto (surjective) functions from a 6-element set to a 3-element set. Total functions = 3^6=729. By inclusion-exclusion, onto functions = 3^6 - 3·2^6 + 3·1^6 = 729-192+3=540.', NULL, 8, 'high', 'high', 210, 'Forgetting to apply inclusion-exclusion and simply assuming each element maps freely, over/undercounting functions that miss one or more codomain elements.'),
  ('CAT2024_QA_S1_12', 2024, 'Slot 1', 'CAT 2024 Slot 1', TRUE, 'PL_CP_SP', 'The selling price of a product is fixed to ensure 40% profit. If the product had cost 40% less and had been sold for 5 rupees less, then the resulting profit would have been 50%. The original selling price, in rupees, of the product is', 'mcq', '20', '15', '14', '10', 'c', 'Let CP=c, SP=1.4c. New CP=0.6c, new SP=1.4c-5=1.5(0.6c)=0.9c. So 1.4c-5=0.9c ⇒ 0.5c=5 ⇒ c=10, SP=1.4×10=14.', NULL, 6, 'medium', 'medium', 150, 'Applying the 50% profit margin to the original cost instead of the reduced (40% less) cost.'),
  ('CAT2024_QA_S1_13', 2024, 'Slot 1', 'CAT 2024 Slot 1', TRUE, 'ALG_LINEAR_WORD', 'There are four numbers such that average of first two numbers is 1 more than the first number, average of first three numbers is 2 more than average of first two numbers, and average of first four numbers is 3 more than average of first three numbers. Then, the difference between the largest and the smallest numbers, is', 'tita', NULL, NULL, NULL, NULL, '15', 'Let first number = x1. Avg(x1,x2)=x1+1 ⇒ x2=x1+2. Avg of first three = x1+3 ⇒ x3=x1+7. Avg of first four = x1+6 ⇒ x4=x1+15. Largest-smallest = x4-x1=15 (assuming x1 is smallest and x4 largest, which holds since the sequence is increasing).', NULL, 6, 'medium', 'medium', 150, 'Errors propagating averages forward into totals, or assuming the wrong number is the maximum/minimum without checking the increasing pattern.'),
  ('CAT2024_QA_S1_14', 2024, 'Slot 1', 'CAT 2024 Slot 1', TRUE, 'SI_BASIC', 'An amount of Rs 10000 is deposited in bank A for a certain number of years at a simple interest of 5% per annum. On maturity, the total amount received is deposited in bank B for another 5 years at a simple interest of 6% per annum. If the interests received from bank A and bank B are in the ratio 10:13, then the investment period, in years, in bank A is', 'mcq', '6', '4', '3', '5', 'a', 'Let period in A = t years. Interest from A = 10000×0.05×t=500t. Maturity amount = 10000+500t. Interest from B over 5 years at 6% = (10000+500t)×0.06×5 = 3000+150t. Given 500t/(3000+150t)=10/13. Solving: 6500t=30000+1500t ⇒ 5000t=30000 ⇒ t=6.', NULL, 6, 'high', 'medium', 180, 'Using the original principal instead of the maturity amount as the base for bank B''s interest calculation.'),
  ('CAT2024_QA_S1_15', 2024, 'Slot 1', 'CAT 2024 Slot 1', TRUE, 'RATIO_BASIC', 'A fruit seller has a total of 187 fruits consisting of apples, mangoes and oranges. The number of apples and mangoes are in the ratio 5:2. After she sells 75 apples, 26 mangoes and half of the oranges, the ratio of number of unsold apples to number of unsold oranges becomes 3:2. The total number of unsold fruits is', 'tita', NULL, NULL, NULL, NULL, '66', 'Let apples=5k, mangoes=2k, oranges=187-7k. Unsold apples=5k-75, unsold oranges=(187-7k)/2. Ratio (5k-75)/((187-7k)/2)=3/2 gives an equation solvable for k; substituting back and summing unsold apples, mangoes(2k-26) and oranges gives total unsold = 66.', NULL, 6, 'high', 'medium', 180, 'Forgetting that only half the oranges are sold (not all), or mixing up which quantity the 3:2 ratio applies to.'),
  ('CAT2024_QA_S1_16', 2024, 'Slot 1', 'CAT 2024 Slot 1', TRUE, 'GEO_TRI_CENTERS', 'ABCD is a rectangle with sides AB=56 cm and BC=45 cm, and E is the midpoint of side CD. Then, the length, in cm, of radius of incircle of △ADE is', 'tita', NULL, NULL, NULL, NULL, '10', 'Place coordinates: A(0,0), D(0,45), C(56,45), so E, midpoint of CD, is (28,45). Triangle ADE has AD=45, DE=28, and AE=√(28²+45²)=√2809=53. It''s right-angled at D. Area=(1/2)·28·45=630. Inradius r=Area/semi-perimeter=630/((45+28+53)/2)=630/63=10.', NULL, 7, 'high', 'high', 210, 'Misplacing the rectangle''s vertices/coordinates, or forgetting the inradius formula r=Area/s for a right triangle.'),
  ('CAT2024_QA_S1_17', 2024, 'Slot 1', 'CAT 2024 Slot 1', TRUE, 'ALG_QUAD_ROOT', 'If the equations x²+mx+9=0, x²+nx+17=0 and x²+(m+n)x+35=0 have a common negative root, then the value of (2m+3n) is', 'tita', NULL, NULL, NULL, NULL, '38', 'Let the common root be α. Subtracting first from third: (n)α+26=0 (using m+n-m=n for the x-coefficient difference and 35-9=26), and similarly subtracting second from third gives relations. Solving the resulting system for α, m, n yields 2m+3n=38.', NULL, 7, 'high', 'high', 210, 'Sign errors when subtracting equations, or assuming the common root is shared by all three pairwise without verifying it''s negative.'),
  ('CAT2024_QA_S1_18', 2024, 'Slot 1', 'CAT 2024 Slot 1', TRUE, 'PERC_BASIC', 'In September, the incomes of Kamal, Amal and Vimal are in the ratio 8:6:5. They rent a house together, and Kamal pays 15%, Amal pays 12% and Vimal pays 18% of their respective incomes to cover the total house rent in that month. In October, the house rent remains unchanged while their incomes increase by 10%, 12% and 15%, respectively. In October, the percentage of their total income that will be paid as house rent, is nearest to', 'mcq', '15.18', '13.26', '12.75', '14.84', 'b', 'Take incomes as 8,6,5 (units). September rent = 8×0.15+6×0.12+5×0.18=1.2+0.72+0.9=2.82. October incomes: 8.8,6.72,5.75; total=21.27. Rent unchanged=2.82. Percentage=2.82/21.27×100≈13.26%.', NULL, 7, 'high', 'medium', 210, 'Recomputing the rent for October instead of keeping it fixed, or using September''s total income instead of October''s in the denominator.'),
  ('CAT2024_QA_S1_19', 2024, 'Slot 1', 'CAT 2024 Slot 1', TRUE, 'ALG_AP', 'Suppose x1, x2, x3, …, x100 are in arithmetic progression such that x5=−4 and 2x6+2x9=x11+x13. Then, x100 equals', 'mcq', '-196', '206', '204', '-194', 'd', 'Write x_n = a + (n−1)d. The condition 2x6 + 2x9 = x11 + x13 becomes 2(a+5d) + 2(a+8d) = (a+10d) + (a+12d), i.e. 4a + 26d = 2a + 22d, so 2a = −4d and a = −2d. Combining with x5 = a + 4d = −4: −2d + 4d = −4 ⇒ d = −2 and a = 4. Then x100 = a + 99d = 4 − 198 = −194.', NULL, 6, 'medium', 'medium', 180, 'Algebraic slip while expanding the given linear condition on terms 6,9,11,13 in terms of a and d.'),
  ('CAT2024_QA_S1_20', 2024, 'Slot 1', 'CAT 2024 Slot 1', TRUE, 'MIX_REPLACEMENT', 'A glass is filled with milk. Two-thirds of its content is poured out and replaced with water. If this process of pouring out two-thirds the content and replacing with water is repeated three more times, then the final ratio of milk to water in the glass, is', 'mcq', '1:26', '1:80', '1:27', '1:81', 'b', 'Each cycle retains 1/3 of the milk fraction present. After 4 total cycles, milk fraction = (1/3)^4=1/81 of the original volume. So milk:water = 1:80.', NULL, 5, 'low', 'medium', 150, 'Confusing ''milk fraction after n cycles'' (1/3)^n with the final ratio milk:water, forgetting to subtract from the whole (1/81 vs 80/81).'),
  ('CAT2024_QA_S1_21', 2024, 'Slot 1', 'CAT 2024 Slot 1', TRUE, 'TSD_RELATIVE', 'Two places A and B are 45 kms apart and connected by a straight road. Anil goes from A to B while Sunil goes from B to A. Starting at the same time, they cross each other in exactly 1 hour 30 minutes. If Anil reaches B exactly 1 hour 15 minutes after Sunil reaches A, the speed of Anil, in km per hour, is', 'mcq', '18', '14', '12', '16', 'c', 'Let Anil''s speed=u, Sunil''s speed=v. They meet after 1.5 hr: 1.5(u+v)=45 ⇒ u+v=30. Time for Anil to cover 45 km = 45/u; for Sunil = 45/v. Given 45/u - 45/v = 1.25. Solving with u+v=30 gives u=12, v=18.', NULL, 6, 'high', 'medium', 180, 'Setting up the 1h15m difference in the wrong direction (Anil slower means Anil takes longer, so 45/u should be greater than 45/v).'),
  ('CAT2024_QA_S1_22', 2024, 'Slot 1', 'CAT 2024 Slot 1', TRUE, 'NS_REMAINDER', 'When 10^100 is divided by 7, the remainder is', 'mcq', '1', '3', '4', '6', 'c', '10 ≡ 3 (mod 7), so 10^100 ≡ 3^100 (mod 7). Powers of 3 mod 7 cycle with period 6: 3, 2, 6, 4, 5, 1. Since 100 = 6(16) + 4, 3^100 matches the 4th entry of the cycle, which is 4. Remainder = 4.', NULL, 5, 'medium', 'medium', 90, 'Using the wrong cyclicity period for powers of 3 mod 7, or miscounting which term in the cycle corresponds to the remainder of the exponent.'),
  ('CAT2024_QA_S3_01', 2024, 'Slot 3', 'CAT 2024 Slot 3', TRUE, 'SET_VENN', 'In a group of 250 students, the percentage of girls was at least 44% and at most 60%. The rest of the students were boys. Each student opted for either swimming or running or both. If 50% of the boys and 80% of the girls opted for swimming while 70% of the boys and 60% of the girls opted for running, then the minimum and maximum possible number of students who opted for both swimming and running, are', 'mcq', '72 and 88, respectively', '75 and 96, respectively', '72 and 80, respectively', '75 and 90, respectively', 'c', 'Let boys=B, girls=G, B+G=250, with G between 110 and 150. Both-activity count = (0.5B+0.8G)+(0.7B+0.6G)-250 = 1.2B+1.4G-250. Substituting B=250-G gives (0.2G+50). This is minimized at G=110 (giving 72) and maximized at G=150 (giving 80).', NULL, 7, 'high', 'high', 210, 'Forgetting the overlap formula (sum of two groups minus total = both), or using the wrong end of the girls'' percentage range for min vs max.'),
  ('CAT2024_QA_S3_02', 2024, 'Slot 3', 'CAT 2024 Slot 3', TRUE, 'ALG_SURDS', 'If (a + b√3)² = 52 + 30√3, where a and b are natural numbers, then a + b equals', 'mcq', '7', '8', '9', '10', 'b', 'Expanding gives a²+3b²=52 and 2ab=30, so ab=15. Testing natural-number factor pairs of 15 (1,15),(3,5),(5,3),(15,1) against a²+3b²=52 shows only a=5,b=3 works, giving a+b=8.', NULL, 6, 'medium', 'medium', 120, 'Not checking all factor pairs of ab=15 against the rational-part equation before picking an answer.'),
  ('CAT2024_QA_S3_03', 2024, 'Slot 3', 'CAT 2024 Slot 3', TRUE, 'ALG_LINEAR_WORD', 'The average of three distinct real numbers is 28. If the smallest number is increased by 7 and the largest number is reduced by 10, the order of the numbers remains unchanged, and the new arithmetic mean becomes 2 more than the middle number, while the difference between the largest and the smallest numbers becomes 64. Then, the largest number in the original set of three numbers is', 'tita', NULL, NULL, NULL, NULL, '70', 'Let x≤y≤z with x+y+z=84. After the changes, (x+7)+y+(z-10)=81, so the new mean 27 equals y+2, giving y=25 and x+z=59. Also (z-10)-(x+7)=64, so z-x=81. Solving the two equations in x and z gives z=70.', NULL, 6, 'medium', 'medium', 180, 'Mixing up which equation uses the adjusted values (x+7, z-10) versus the original values.'),
  ('CAT2024_QA_S3_04', 2024, 'Slot 3', 'CAT 2024 Slot 3', TRUE, 'NS_REMAINDER', 'If 10^68 is divided by 13, the remainder is', 'mcq', '5', '8', '9', '4', 'c', '1000 ≡ -1 (mod 13). Write 10^68 = (10^66)(100) = (1000^22)(100). Since 1000≡-1, 1000^22≡1. And 100≡9 (mod 13). So the remainder is 1×9=9.', NULL, 6, 'medium', 'medium', 120, 'Not spotting that 1000 leaves remainder -1 mod 13, leading to a much longer cyclicity search.'),
  ('CAT2024_QA_S3_05', 2024, 'Slot 3', 'CAT 2024 Slot 3', TRUE, 'TW_COMBINED', 'Sam can complete a job in 20 days when working alone. Mohit is twice as fast as Sam and thrice as fast as Ayna in the same job. They undertake a job with an arrangement where Sam and Mohit work together on the first day, Sam and Ayna on the second day, Mohit and Ayna on the third day, and this three-day pattern is repeated till the work gets completed. Then, the fraction of total work done by Sam is', 'mcq', '1/20', '3/10', '1/5', '3/20', 'b', 'Take total work = 60 units, so Sam=3, Mohit=6, Ayna=2 units/day. Each 3-day cycle: day1(Sam+Mohit)=9, day2(Sam+Ayna)=5, day3(Mohit+Ayna)=8, total 22 units/cycle. After 2 cycles (6 days), 44 units done, 16 remain. Day7 Sam+Mohit finish 9 (7 left), day8 Sam+Ayna finish 5 (2 left), day9 Mohit+Ayna finish the rest. Sam worked on days 1,2,4,5,7,8 = 6 days × 3 units = 18 units out of 60 = 3/10.', NULL, 7, 'high', 'high', 180, 'Losing track of which pair works on which day of the cycle, or forgetting Sam doesn''t work on the 9th (final) day.'),
  ('CAT2024_QA_S3_06', 2024, 'Slot 3', 'CAT 2024 Slot 3', TRUE, 'GEO_SECTOR', 'A circular plot of land is divided into two regions by a chord of length 10√3 meters such that the chord subtends an angle of 120° at the center. Then, the area, in square meters, of the smaller region is', 'mcq', '20(4π/3 + √3)', '25(4π/3 + √3)', '20(4π/3 − √3)', '25(4π/3 − √3)', 'd', 'Using the cosine rule on the isosceles triangle with the 120° angle and chord 10√3, the radius works out to 10. Sector area = (120/360)π(10)²=100π/3. Triangle area = (1/2)(10)(10)sin120° = 75/√3 = 25√3. Smaller (minor segment) area = sector − triangle = 100π/3 − 25√3 = 25(4π/3 − √3).', NULL, 7, 'high', 'medium', 180, 'Using the major segment/sector instead of the minor one, or an arithmetic slip converting 75/√3 to 25√3.'),
  ('CAT2024_QA_S3_07', 2024, 'Slot 3', 'CAT 2024 Slot 3', TRUE, 'ALG_RECURRENCE', 'Consider the sequence t1=1, t2=−1 and t_n = ((n−3)/(n−1))·t_(n−2) for n≥3. Then, the value of the sum 1/t2 + 1/t4 + 1/t6 + … + 1/t2022 + 1/t2024, is', 'mcq', '-1024144', '-1022121', '-1023132', '-1026169', 'a', 'Apply the recurrence to the even indices: t2 = −1, t4 = (1/3)t2 = −1/3, t6 = (3/5)t4 = −1/5, t8 = (5/7)t6 = −1/7. The pattern is t_(2k) = −1/(2k−1), so 1/t_(2k) = −(2k−1). The required sum runs to t2024, i.e. k = 1 to 1012, giving −(1 + 3 + 5 + ⋯ + 2023). The sum of the first 1012 odd numbers is 1012² = 1024144, so the answer is −1024144.', NULL, 8, 'high', 'high', 210, 'Not recognizing the even-term pattern early and instead trying to compute all 1012 terms individually.'),
  ('CAT2024_QA_S3_08', 2024, 'Slot 3', 'CAT 2024 Slot 3', TRUE, 'ALG_SPECIAL', 'The number of distinct real values of x, satisfying the equation max{x,2} − min{x,2} = |x+2| − |x−2|, is', 'tita', NULL, NULL, NULL, NULL, '2', 'For x≥2: LHS=x-2, RHS=4, giving x=6 (valid). For x≤-2: LHS=2-x (positive), RHS=-4 (negative), no solution. For -2<x<2: LHS=2-x, RHS=2x, giving x=2/3 (valid). So there are 2 real solutions.', NULL, 7, 'medium', 'high', 180, 'Forgetting max{x,2}-min{x,2} can never be negative, which rules out the -2<x<2... region incorrectly, or mishandling the sign of RHS in each zone.'),
  ('CAT2024_QA_S3_09', 2024, 'Slot 3', 'CAT 2024 Slot 3', TRUE, 'CI_ANNUAL', 'Aman invests Rs 4000 in a bank at a certain rate of interest, compounded annually. If the ratio of the value of the investment after 3 years to the value of the investment after 5 years is 25:36, then the minimum number of years required for the value of the investment to exceed Rs 20000 is', 'tita', NULL, NULL, NULL, NULL, '9', 'Ratio of amounts after 3 and 5 years gives (1+r)²=36/25, so 1+r=1.2 (r=20%). We need 4000(1.2)^n>20000, i.e. (1.2)^n>5. Since 1.2^8≈4.30 and 1.2^9≈5.16, the minimum n is 9.', NULL, 6, 'medium', 'medium', 180, 'Taking the square root of 36/25 incorrectly, or rounding 1.2^8 and 1.2^9 too coarsely to tell which side of 5 they land on.'),
  ('CAT2024_QA_S3_10', 2024, 'Slot 3', 'CAT 2024 Slot 3', TRUE, 'ALG_EXP', 'The sum of all distinct real values of x that satisfy the equation 10^x + 4/10^x = 81/2, is', 'mcq', '2 log10 2', '4 log10 2', 'log10 2', '3 log10 2', 'a', 'Let a=10^x. Then a+4/a=81/2 gives 2a²-81a+8=0. The product of roots a1·a2 = 8/2 = 4. Since x1=log a1 and x2=log a2, the sum x1+x2 = log(a1·a2) = log4 = 2log2.', NULL, 6, 'medium', 'medium', 150, 'Trying to solve the quadratic explicitly for both roots instead of using the product-of-roots shortcut for the sum of logs.'),
  ('CAT2024_QA_S3_11', 2024, 'Slot 3', 'CAT 2024 Slot 3', TRUE, 'TSD_BASIC', 'A train travelled a certain distance at a uniform speed. Had the speed been 6 km per hour more, it would have needed 4 hours less. Had the speed been 6 km per hour less, it would have needed 6 hours more. The distance, in km, travelled by the train is', 'mcq', '720', '800', '780', '640', 'a', 'Let speed=S, time=t, distance D=St. From the first condition D=(S+6)(t-4); from the second D=(S-6)(t+6). Expanding both and equating with D=St leads to two linear equations in S and t, which solve to S=30 kmph, t=24 hours, giving D=720 km.', NULL, 7, 'high', 'medium', 180, 'Sign errors while expanding (S+6)(t-4) and (S-6)(t+6), or forgetting D=St must be used to eliminate one variable.'),
  ('CAT2024_QA_S3_12', 2024, 'Slot 3', 'CAT 2024 Slot 3', TRUE, 'ALG_LOG', 'If 3^a=4, 4^b=5, 5^c=6, 6^d=7, 7^e=8 and 8^f=9, then the value of the product abcdef is', 'tita', NULL, NULL, NULL, NULL, '2', 'Take logs: a = log4/log3, b = log5/log4, c = log6/log5, d = log7/log6, e = log8/log7, f = log9/log8. The product telescopes — every numerator cancels the next denominator — leaving abcdef = log9/log3 = log₃9 = 2.', NULL, 7, 'medium', 'medium', 180, 'Not recognizing the telescoping chain, leading to trying to compute each log numerically instead.'),
  ('CAT2024_QA_S3_13', 2024, 'Slot 3', 'CAT 2024 Slot 3', TRUE, 'PL_DISCOUNT', 'Gopi marks a price on a product in order to make 20% profit. Ravi gets 10% discount on this marked price, and thus saves Rs 15. Then, the profit, in rupees, made by Gopi by selling the product to Ravi, is', 'mcq', '10', '25', '15', '20', 'a', 'Let cost price=X, marked price=1.2X. Ravi''s discounted price = 0.9(1.2X)=1.08X, and the saving is 1.2X-1.08X=0.12X=15, so X=125. Gopi''s actual profit = 1.08X-X=0.08X=0.08(125)=10.', NULL, 6, 'medium', 'medium', 120, 'Assuming Gopi still earns the full 20% profit after the discount, instead of recomputing profit on the discounted selling price.'),
  ('CAT2024_QA_S3_14', 2024, 'Slot 3', 'CAT 2024 Slot 3', TRUE, 'MIX_REPLACEMENT', 'A certain amount of water was poured into a 300 litre container and the remaining portion of the container was filled with milk. Then an amount of this solution was taken out from the container which was twice the volume of water that was earlier poured into it, and water was poured to refill the container again. If the resulting solution contains 72% milk, then the amount of water, in litres, that was initially poured into the container was', 'tita', NULL, NULL, NULL, NULL, '30', 'Let initial water=Y, milk=300-Y. Removing 2Y litres of the uniform mixture removes a 2Y/300 fraction of the milk too, leaving milk = (300-Y)(1-2Y/300) = 72% of 300 = 216. Simplifying gives (300-Y)(300-2Y)=64800, a quadratic with roots Y=30 or Y=420; since Y must be under 300, Y=30.', NULL, 7, 'high', 'high', 210, 'Assuming only water is removed in the 2Y-litre extraction, rather than a proportional mix of milk and water.'),
  ('CAT2024_QA_S3_15', 2024, 'Slot 3', 'CAT 2024 Slot 3', TRUE, 'GEO_POLY', 'A regular octagon ABCDEFGH has sides of length 6 cm each. Then the area, in sq. cm, of the square ACEG is', 'mcq', '72(2+√2)', '36(1+√2)', '72(1+√2)', '36(2+√2)', 'd', 'Each interior angle of a regular octagon is 135°. Using the cosine rule in triangle ABC with AB=BC=6 and angle B=135°, AC² = 36+36-2(36)cos135° = 72+36√2 = 36(2+√2). Since AC is a side of square ACEG, its area equals AC² = 36(2+√2).', NULL, 7, 'high', 'high', 210, 'Using the wrong interior angle for a regular octagon (should be 135°, not 120° or 108°), or forgetting cos135° is negative.'),
  ('CAT2024_QA_S3_16', 2024, 'Slot 3', 'CAT 2024 Slot 3', TRUE, 'ALG_INEQ_MOD', 'The number of distinct integer solutions (x, y) of the equation |x+y| + |x−y| = 2, is', 'tita', NULL, NULL, NULL, NULL, '8', '|x+y|+|x-y| equals 2·max(|x|,|y|). So we need max(|x|,|y|)=1 with x,y integers. This gives all integer pairs with |x|≤1,|y|≤1 except those with max<1, i.e. the 8 boundary points: (±1,0),(0,±1),(±1,±1) — checking each against the original equation confirms 8 valid pairs.', NULL, 6, 'medium', 'high', 180, 'Not recognizing the identity |x+y|+|x-y|=2max(|x|,|y|), which makes the counting much slower and error-prone if done case-by-case.'),
  ('CAT2024_QA_S3_17', 2024, 'Slot 3', 'CAT 2024 Slot 3', TRUE, 'ALG_FUNC_COMP', 'For any non-zero real number x, let f(x) + 2f(1/x) = 3x. Then, the sum of all possible values of x for which f(x)=3, is', 'mcq', '3', '-2', '-3', '2', 'c', 'Substitute 1/x for x to get a second equation f(1/x)+2f(x)=3/x. Multiply this by 2 and subtract the original: 3f(x) = 6/x - 3x, so f(x) = 2/x - x. Setting f(x)=3 gives 2/x - x = 3, i.e. x²+3x-2=0, whose roots sum to -3 (using sum of roots = -b/a).', NULL, 7, 'medium', 'high', 180, 'Errors while eliminating f(1/x) between the two equations, or forgetting to apply the sum-of-roots shortcut at the end.'),
  ('CAT2024_QA_S3_18', 2024, 'Slot 3', 'CAT 2024 Slot 3', TRUE, 'ALG_LINEAR_2', 'For some constant real numbers p, k and a, consider the following system of linear equations in x and y: px - 4y = 2; 3x + ky = a. A necessary condition for the system to have no solution for (x, y), is', 'mcq', 'ap + 6 = 0', '2a + k ≠ 0', 'ap − 6 = 0', 'kp + 12 ≠ 0', 'b', 'No solution requires the lines to be parallel but not identical: p/3 = -4/k ≠ 2/a. The first part gives pk=-12. The ''not identical'' part requires -4/k ≠ 2/a, i.e. k ≠ -2a, i.e. k+2a≠0, which is option B.', NULL, 6, 'medium', 'high', 180, 'Only checking the ''parallel'' condition (equal ratios of x,y coefficients) and forgetting the additional ''not proportional to the constant term'' condition needed to rule out infinite solutions.'),
  ('CAT2024_QA_S3_19', 2024, 'Slot 3', 'CAT 2024 Slot 3', TRUE, 'RATIO_BASIC', 'Rajesh and Vimal own 20 hectares and 30 hectares of agricultural land, respectively, which are entirely covered by wheat and mustard crops. The cultivation area of wheat and mustard in the land owned by Vimal are in the ratio of 5:3. If the total cultivation area of wheat and mustard are in the ratio 11:9, then the ratio of cultivation area of wheat and mustard in the land owned by Rajesh is', 'mcq', '4:3', '7:9', '3:7', '1:1', 'b', 'Vimal''s wheat=18.75, mustard=11.25 (from 5:3 of 30). Let Rajesh''s wheat:mustard = k:1 of his 20 hectares. Total wheat:mustard = 11:9 gives an equation in k which solves to k=7/9, i.e. wheat:mustard = 7:9 for Rajesh.', NULL, 7, 'high', 'medium', 180, 'Mixing up which owner''s ratio is already known (Vimal) versus which is being solved for (Rajesh), or an arithmetic slip while cross-multiplying the combined ratio equation.'),
  ('CAT2024_QA_S3_20', 2024, 'Slot 3', 'CAT 2024 Slot 3', TRUE, 'GEO_TRI_SIM', 'The midpoints of sides AB, BC, and AC in △ABC are M, N, and P, respectively. The medians drawn from A, B, and C intersect the line segments MP, MN and NP at X, Y, and Z, respectively. If the area of △ABC is 1440 sq cm, then the area, in sq cm, of △XYZ is', 'tita', NULL, NULL, NULL, NULL, '90', 'Triangle MNP (the medial triangle) is similar to ABC with a 1:2 side ratio, so its area is 1440/4=360. By the same medial-triangle logic applied one level down, X, Y, Z form a triangle similar to MNP with the same 1:2 ratio, so its area is 360/4=90.', NULL, 7, 'medium', 'high', 210, 'Applying the 1/4 area-scaling only once instead of recognizing the pattern repeats for the inner triangle XYZ as well.'),
  ('CAT2024_QA_S3_21', 2024, 'Slot 3', 'CAT 2024 Slot 3', TRUE, 'MOD_COUNT', 'The number of all positive integers up to 500 with non-repeating digits is', 'tita', NULL, NULL, NULL, NULL, '378', '1-digit: 9 numbers. 2-digit: 9 choices for tens digit (1-9) × 9 for units (0-9 excluding tens digit) = 81. 3-digit up to 500: hundreds digit ∈{1,2,3,4} (4 choices), tens digit 9 remaining choices, units digit 8 remaining choices = 4×9×8=288. Total = 9+81+288=378.', NULL, 6, 'medium', 'medium', 210, 'Allowing the hundreds digit to be 5 or more (numbers must stay ≤500), or forgetting numbers can''t start with 0.'),
  ('CAT2024_QA_S3_22', 2024, 'Slot 3', 'CAT 2024 Slot 3', TRUE, 'PERC_SUCCESSIVE', 'After two successive increments, Gopal''s salary became 187.5% of his initial salary. If the percentage of salary increase in the second increment was twice of that in the first increment, then the percentage of salary increase in the first increment was', 'mcq', '30', '27.5', '25', '20', 'c', 'Let the first increment be z (as a fraction). (1+z)(1+2z)=1.875. Expanding: 2z²+3z-0.875=0. Solving the quadratic gives z=0.25, i.e. 25%.', NULL, 6, 'medium', 'medium', 150, 'Assuming the two increments simply add to 87.5% instead of compounding multiplicatively.'),
  ('CAT2024_QA_S2_01', 2024, 'Slot 2', 'CAT 2024 Slot 2', TRUE, 'PL_CP_SP', 'Bina incurs 19% loss when she sells a product at Rs. 4860 to Shyam, who in turn sells this product to Hari. If Bina would have sold this product to Shyam at the purchase price of Hari, she would have obtained 17% profit. Then, the profit, in rupees, made by Shyam is', 'tita', NULL, NULL, NULL, NULL, '2160', 'Bina''s cost price: 0.81C=4860, so C=6000. If Bina had sold at 17% profit, that selling price (which equals Hari''s purchase price from Shyam) would be 1.17×6000=7020. Shyam bought at 4860 and sold at 7020, profit = 7020-4860=2160.', NULL, 6, 'medium', 'medium', 150, 'Confusing whose cost price and whose selling price is being asked at each stage of the resale chain.'),
  ('CAT2024_QA_S2_02', 2024, 'Slot 2', 'CAT 2024 Slot 2', TRUE, 'GEO_TRI_CENTERS', 'The coordinates of the three vertices of a triangle are: (1, 2), (7, 2), and (1, 10). Then the radius of the incircle of the triangle is', 'tita', NULL, NULL, NULL, NULL, '2', 'This is a right triangle with legs 6 and 8 (along the horizontal and vertical from (1,2)) and hypotenuse 10. Area=(1/2)(6)(8)=24, semi-perimeter=(6+8+10)/2=12. Inradius = Area/semi-perimeter = 24/12 = 2.', NULL, 6, 'medium', 'medium', 150, 'Miscomputing the leg lengths from coordinates, or forgetting the r=Area/s inradius formula.'),
  ('CAT2024_QA_S2_03', 2024, 'Slot 2', 'CAT 2024 Slot 2', TRUE, 'PERC_BASIC', 'A fruit seller has a stock of mangoes, bananas and apples with at least one fruit of each type. At the beginning of a day, the number of mangoes make up 40% of his stock. That day, he sells half of the mangoes, 96 bananas and 40% of the apples. At the end of the day, he ends up selling 50% of the fruits. The smallest possible total number of fruits in the stock at the beginning of the day is', 'tita', NULL, NULL, NULL, NULL, '340', 'Let total stock=S and apples=a. Mangoes=2S/5. Fruits sold = S/5+96+2a/5 = S/2, giving S=(4a+960)/3 = 4a/3+320. For S to be an integer, a must be a multiple of 3; for 2a/5 (apples sold) to be an integer, a must be a multiple of 5. Smallest such a is 15, giving S = 4(15)/3+320 = 340.', NULL, 8, 'high', 'high', 240, 'Missing one of the two divisibility conditions on ''a'' (multiple of 3 from the S formula, multiple of 5 from apples sold), which leads to a non-minimal or invalid answer.'),
  ('CAT2024_QA_S2_04', 2024, 'Slot 2', 'CAT 2024 Slot 2', TRUE, 'ALG_LOG', 'If a, b and c are positive real numbers such that a > 10 ≥ b ≥ c and log8(a+b)/log2(c) + log27(a-b)/log3(c) = 2/3, then the greatest possible integer value of a is', 'tita', NULL, NULL, NULL, NULL, '14', 'Converting each term to base c using change-of-base gives logc(a+b)^(1/3) + logc(a-b)^(1/3) = logc[(a²-b²)^(1/3)] = 2/3, so c^2=a²-b², i.e. a²=b²+c². With b,c≤10, a² is maximized near b=c=10 (a² close to 200), and the largest perfect square below 200 achievable is 196, giving a=14.', NULL, 8, 'high', 'high', 240, 'Errors converting log base 8 and 27 to base 2 and 3 respectively (dividing by the wrong factor of 3), or forgetting a must be an integer, not just satisfy the inequality.'),
  ('CAT2024_QA_S2_05', 2024, 'Slot 2', 'CAT 2024 Slot 2', TRUE, 'ALG_FUNC_COMP', 'A function f maps the set of natural numbers to whole numbers, such that f(xy) = f(x)f(y) + f(x) + f(y) for all x, y and f(p) = 1 for every prime number p. Then, the value of f(160000) is', 'mcq', '4095', '8191', '2047', '1023', 'a', '160000=2^8×5^4. Using f(p)=1 repeatedly, f(p²)=3, f(p³)=7, f(p^4)=15, doubling and adding 1 each time; this gives f(p^8)=255 and f(p^4)=15. Then f(2^8×5^4)=f(2^8)f(5^4)+f(2^8)+f(5^4) = 255×15+255+15 = 4095.', NULL, 7, 'high', 'high', 210, 'Not spotting the pattern f(p^(k+1))=2f(p^k)+1, leading to a slow or error-prone term-by-term buildup.'),
  ('CAT2024_QA_S2_06', 2024, 'Slot 2', 'CAT 2024 Slot 2', TRUE, 'ALG_QUAD_ROOT', 'The roots α, β of the equation 3x² + λx − 1 = 0, satisfy 1/α² + 1/β² = 15. The value of (α³+β³)², is', 'mcq', '16', '4', '1', '9', 'b', 'α+β=-λ/3, αβ=-1/3. The given condition becomes (α²+β²)/(αβ)²=15, so α²+β²=15/9. Using α²+β²=(α+β)²-2αβ gives λ²=9. Then α³+β³=(α+β)³-3αβ(α+β), which simplifies using λ²=9 to a value whose square is 4.', NULL, 7, 'high', 'high', 210, 'Sign errors when substituting λ²=9 back (both λ=3 and λ=-3 need checking, though the final squared answer is the same).'),
  ('CAT2024_QA_S2_07', 2024, 'Slot 2', 'CAT 2024 Slot 2', TRUE, 'ALG_LINEAR_WORD', 'When Rajesh''s age was same as the present age of Garima, the ratio of their ages was 3:2. When Garima''s age becomes the same as the present age of Rajesh, the ratio of the ages of Rajesh and Garima will become', 'mcq', '3:2', '4:3', '5:4', '2:1', 'c', 'Let R=G+x (Rajesh is x years older). x years ago Garima was G-x and Rajesh was G; ratio G/(G-x)=3/2 gives G=3x, so R=4x. When Garima reaches age 4x (in x more years), Rajesh will be 5x. Ratio = 5x:4x = 5:4.', NULL, 6, 'medium', 'high', 180, 'Getting the time direction backward (looking x years into the future for Garima instead of x years into the past for the given condition).'),
  ('CAT2024_QA_S2_08', 2024, 'Slot 2', 'CAT 2024 Slot 2', TRUE, 'GEO_CIRCLE_TANGENT', 'Three circles of equal radii touch (but not cross) each other externally. Two other circles, X and Y, are drawn such that both touch (but not cross) each of the three previous circles. If the radius of X is more than that of Y, the ratio of the radii of X and Y is', 'mcq', '7+4√3 : 1', '4+2√3 : 1', '4+√3 : 1', '2+√3 : 1', 'a', 'Joining centres of the three equal circles (radius R) gives an equilateral triangle of side 2R. For the small inner circle (radius r) touching all three, R/(R+r)=√3/2, giving r=(2-√3)R. The large outer circle (radius = 2R+r) touching all three externally gives the ratio (2R+r)/r = (2+√3)/(2-√3) = 7+4√3, after rationalizing.', NULL, 8, 'high', 'high', 240, 'Mixing up the inner (small, between the three circles) and outer (large, enclosing all three) tangent circles when assigning which is X and which is Y.'),
  ('CAT2024_QA_S2_09', 2024, 'Slot 2', 'CAT 2024 Slot 2', TRUE, 'GEO_TRI_SIM', 'ABCD is a trapezium in which AB is parallel to CD. The sides AD and BC when extended, intersect at point E. If AB = 2 cm, CD = 1 cm, and perimeter of ABCD is 6 cm, then the perimeter, in cm, of △AEB is', 'mcq', '8', '10', '9', '7', 'a', 'Since AB=2×CD, and triangles AEB and DEC are similar with this 2:1 ratio, D and C are midpoints of AE and BE. So AD=DE=x and BC=CE=3-x (since AD+BC=6-2-1=3). This makes AE=2x and BE=6-2x. Perimeter of AEB = AE+BE+AB = 2x+(6-2x)+2 = 8.', NULL, 6, 'medium', 'high', 180, 'Not recognizing that AB=2×CD forces D, C to be exact midpoints of AE, BE, which is the key simplification.'),
  ('CAT2024_QA_S2_10', 2024, 'Slot 2', 'CAT 2024 Slot 2', TRUE, 'ALG_LINEAR_WORD', 'A company has 40 employees whose names are listed in a certain order. In the year 2022, the average bonus of the first 30 employees was Rs. 40000, of the last 30 employees was Rs. 60000, and of the first 10 and last 10 employees together was Rs. 50000. Next year, the average bonus of the first 10 employees increased by 100%, of the last 10 employees increased by 200% and of the remaining employees was unchanged. Then, the average bonus, in rupees, of all the 40 employees together in the year 2023 was', 'mcq', '95000', '90000', '80000', '85000', 'a', 'Split the 40 employees into four blocks of 10 and let a, b, c, d be the block totals. First 30 average 40000 ⇒ a+b+c = 1200000. Last 30 average 60000 ⇒ b+c+d = 1800000. First 10 and last 10 together (20 people) average 50000 ⇒ a+d = 1000000. Adding the first two equations: a + 2(b+c) + d = 3000000, so 2(b+c) = 2000000 and b+c = 1000000. Hence a = 200000 and d = 800000. In 2023 the first block rises 100% to 400000, the last block rises 200% to 3 × 800000 = 2400000, and the middle 20 are unchanged at 1000000. New total = 3800000, so the average over 40 employees = 95000.', NULL, 7, 'high', 'high', 210, 'Confusing ''increased by 200%'' with ''becomes 200% of original'' (should be 3×, not 2×, the original).'),
  ('CAT2024_QA_S2_11', 2024, 'Slot 2', 'CAT 2024 Slot 2', TRUE, 'TW_COMBINED', 'Amal and Vimal together can complete a task in 150 days, while Vimal and Sunil together can complete the same task in 100 days. Amal starts working on the task and works for 75 days, then Vimal takes over and works for 135 days. Finally, Sunil takes over and completes the remaining task in 45 days. If Amal had started the task alone and worked on all days, Vimal had worked on every second day, and Sunil had worked on every third day, then the number of days required to complete the task would have been', 'tita', NULL, NULL, NULL, NULL, '139', 'From 150(A+V)=T and 100(V+S)=T and 75A+135V+45S=T, solving simultaneously gives S=2V and A=V, with T=300V. In each 6-day cycle (LCM of 1,2,3), Amal works 6 days (6V units), Vimal works 3 days (3V), Sunil works 2 days (4V), totaling 13V units per cycle. 300V/13V≈23 cycles (138 days) completes 299V units, leaving 1V unit for day 139.', NULL, 8, 'high', 'high', 240, 'Using the wrong LCM cycle length, or forgetting Sunil''s daily rate is 2V (not V) since S=2V from the derived relations.'),
  ('CAT2024_QA_S2_12', 2024, 'Slot 2', 'CAT 2024 Slot 2', TRUE, 'ALG_INEQ_QUAD', 'All the values of x satisfying the inequality 1/(x+5) ≤ 1/(2x−3) are', 'mcq', 'x < −5 or 3/2 < x ≤ 8', '−5 < x < 3/2 or x > 3/2', 'x < −5 or x > 3/2', '−5 < x < 3/2 or 3/2 < x ≤ 8', 'a', 'Critical points are x=-5 and x=3/2. Testing each region: for x>3/2, cross-multiplying (both denominators positive) gives 2x-3≤x+5, i.e. x≤8, so 3/2<x≤8 works. For -5<x<3/2, testing shows the inequality fails. For x<-5, both denominators negative, giving the same boundary x≤8, which is automatically true, so all x<-5 works.', NULL, 6, 'high', 'high', 180, 'Cross-multiplying without checking the sign of each denominator in every region, which flips the inequality incorrectly.'),
  ('CAT2024_QA_S2_13', 2024, 'Slot 2', 'CAT 2024 Slot 2', TRUE, 'CI_ANNUAL', 'Anil invests Rs 22000 for 6 years in a scheme with 4% interest per annum, compounded half-yearly. Separately, Sunil invests a certain amount in the same scheme for 5 years, and then reinvests the entire amount he receives at the end of 5 years, for one year at 10% simple interest. If the amounts received by both at the end of 6 years are equal, then the initial investment, in rupees, made by Sunil is', 'mcq', '20860', '20640', '20480', '20808', 'd', 'Anil''s maturity = 22000(1.02)^12. Sunil''s amount after 5 years (10 half-year periods) is X(1.02)^10, which then earns 10% simple interest for a year: X(1.02)^10(1.1). Equating: X(1.02)^10(1.1)=22000(1.02)^12, so X = 22000(1.02)²/1.1 = 20808.', NULL, 7, 'high', 'medium', 210, 'Using 6 years (12 half-year periods) for Sunil''s compounding phase instead of 5 years (10 periods), since the last year is simple, not compound, interest.'),
  ('CAT2024_QA_S2_14', 2024, 'Slot 2', 'CAT 2024 Slot 2', TRUE, 'TSD_BASIC', 'A bus starts at 9 am and follows a fixed route every day. One day, it traveled at a constant speed of 60 km per hour and reached its destination 3.5 hours later than its scheduled arrival time. Next day, it traveled two-thirds of its route in one-third of its total scheduled travel time, and the remaining part of the route at 40 km per hour to reach just on time. The scheduled arrival time of the bus is', 'mcq', '7:30 pm', '7:00 pm', '9:00 pm', '10:30 pm', 'a', 'Let scheduled time=t hours. Distance=60(t+3.5). On day two, the last third of the time (2t/3 hours) covers the remaining third of the distance at 40 km/h, so distance/3 = 40(2t/3), giving distance=80t. Equating 60(t+3.5)=80t gives t=10.5 hours. Starting at 9 am, arrival is at 7:30 pm.', NULL, 7, 'high', 'high', 210, 'Misreading which fraction of distance/time applies to which speed segment on the second day.'),
  ('CAT2024_QA_S2_15', 2024, 'Slot 2', 'CAT 2024 Slot 2', TRUE, 'ALG_INDICES', 'If m and n are natural numbers such that n > 1, and m^n = 2^25 × 3^40, then m − n equals', 'mcq', '209932', '209937', '209942', '209947', 'd', 'For m^n to work with both exponents 25 and 40, n must be a common factor of both; the largest common factor (other than 1) is 5. So n=5, and m = 2^5×3^8 = 32×6561 = 209952. Then m-n = 209952-5 = 209947.', NULL, 7, 'medium', 'medium', 180, 'Using n=1 (not allowed, since n>1) or another common factor of 25 and 40 instead of the largest valid one (5).'),
  ('CAT2024_QA_S2_16', 2024, 'Slot 2', 'CAT 2024 Slot 2', TRUE, 'NS_REMAINDER', 'When 3^333 is divided by 11, the remainder is', 'mcq', '5', '10', '1', '6', 'a', '3^5=243 leaves remainder 1 mod 11 (since 242=11×22). Write 333=5×66+3, so 3^333=(3^5)^66×3^3≡1^66×27≡5 (mod 11).', NULL, 6, 'medium', 'medium', 150, 'Using the wrong power of 3 as the cyclicity base instead of 3^5=243, which is the one that actually gives remainder 1.'),
  ('CAT2024_QA_S2_17', 2024, 'Slot 2', 'CAT 2024 Slot 2', TRUE, 'ALG_SPECIAL', 'If x and y are real numbers such that 4x² + 4y² − 4xy − 6y + 3 = 0, then the value of (4x+5y) is', 'tita', NULL, NULL, NULL, NULL, '7', 'Rewrite 4x²-4xy+y²=(2x-y)², leaving 3y²-6y+3 as the rest, i.e. (2x-y)²+3(y-1)²=0. Since both squared terms are non-negative, both must be zero: y=1 and then 2x=y=1, so x=1/2. Then 4x+5y=2+5=7.', NULL, 7, 'medium', 'high', 180, 'Missing that the equation is a sum of two perfect squares set to zero, and instead trying to solve it as a general two-variable equation.'),
  ('CAT2024_QA_S2_18', 2024, 'Slot 2', 'CAT 2024 Slot 2', TRUE, 'ALG_SURDS', 'If (x+6√2)^(1/2) − (x−6√2)^(1/2) = 2√2, then x equals', 'tita', NULL, NULL, NULL, NULL, '11', 'Squaring both sides: (x+6√2)+(x-6√2)-2√((x+6√2)(x-6√2)) = 8, i.e. 2x-2√(x²-72)=8, so x-√(x²-72)=4. Isolating and squaring again: x²-72=(x-4)²=x²-8x+16, giving 8x=88, x=11.', NULL, 7, 'medium', 'medium', 180, 'Sign error when isolating the square root term before the second squaring step.'),
  ('CAT2024_QA_S2_19', 2024, 'Slot 2', 'CAT 2024 Slot 2', TRUE, 'MOD_COUNT', 'P, Q, R and S are four towns. One can travel between P and Q along 3 direct paths, between Q and S along 4 direct paths, and between P and R along 4 direct paths. There is no direct path between P and S, while there are few direct paths between Q and R, and between R and S. One can travel from P to S either via Q, or via R, or via Q followed by R, respectively, in exactly 62 possible ways. One can also travel from Q to R either directly, or via P, or via S, in exactly 27 possible ways. Then, the number of direct paths between Q and R is', 'tita', NULL, NULL, NULL, NULL, '7', 'Let paths Q-R=b and R-S=a. Route P to S: via Q(=3×4=12), via R(=4a), via Q-R(=3×b×a); total 4a+3ab+12=62, i.e. 4a+3ab=50. Route Q to R: direct=b, via P(=3×4=12), via S(=4×a); total b+12+4a=27, i.e. 4a+b=15. Subtracting gives b(3a-1)=35. Testing valid factor combinations of 35 against 4a+b=15 shows b=7, a=2 works consistently.', NULL, 8, 'high', 'high', 240, 'Missing one of the three route types when building either of the two count equations, or not checking each candidate factor pair of 35 against both equations.'),
  ('CAT2024_QA_S2_20', 2024, 'Slot 2', 'CAT 2024 Slot 2', TRUE, 'ALG_INEQ_MOD', 'If x and y satisfy the equations |x| + x + y = 15 and x + |y| − y = 20, then (x−y) equals', 'mcq', '20', '15', '5', '10', 'b', 'If x were negative, |x|+x=0, making the first equation y=15; then testing shows x must be positive for the second equation to hold consistently, a contradiction. Testing x>0 and y<0 works: first equation becomes 2x+y=15, second becomes x-2y=20. Solving simultaneously gives x=10, y=-5, so x-y=15.', NULL, 6, 'medium', 'high', 150, 'Not testing all four sign combinations of x and y systematically before settling on the consistent one.'),
  ('CAT2024_QA_S2_21', 2024, 'Slot 2', 'CAT 2024 Slot 2', TRUE, 'MIX_ALLIGATION', 'A vessel contained a certain amount of a solution of acid and water. When 2 litres of water was added to it, the new solution had 50% acid concentration. When 15 litres of acid was further added to this new solution, the final solution had 80% acid concentration. The ratio of water and acid in the original solution was', 'mcq', '5:3', '3:5', '5:4', '4:5', 'b', 'After the 50% stage, let the solution be T acid + T water (2T total). Adding 15 litres of acid: (T+15)/(2T+15)=4/5, solving gives T=5. So after adding 2L water there were 5L acid and 5L water; before that, water was 5-2=3L and acid was still 5L. Ratio water:acid = 3:5.', NULL, 7, 'medium', 'medium', 180, 'Forgetting to subtract the 2 litres of added water back out when reporting the original (pre-addition) ratio.'),
  ('CAT2024_QA_S2_22', 2024, 'Slot 2', 'CAT 2024 Slot 2', TRUE, 'ALG_GP', 'The sum of the infinite series (1/5)[(1/5)−(1/7)] + (1/5)²[(1/5)²−(1/7)²] + (1/5)³[(1/5)³−(1/7)³] + … is equal to', 'mcq', '7/816', '5/408', '7/408', '5/816', 'b', 'The k-th term is (1/5)^k[(1/5)^k − (1/7)^k] = (1/25)^k − (1/35)^k, so the series splits into two geometric series. First: ratio 1/25, sum = (1/25)/(1 − 1/25) = 1/24. Second: ratio 1/35, sum = (1/35)/(1 − 1/35) = 1/34. Total = 1/24 − 1/34 = (34 − 24)/816 = 10/816 = 5/408.', NULL, 8, 'high', 'high', 210, 'Combining the two parts of each bracket incorrectly instead of splitting into two clean geometric series with ratios 1/25 and 1/35 respectively.'),
  ('CAT2025_QA_S1_01', 2025, 'Slot 1', 'CAT 2025 Slot 1', TRUE, 'ALG_FUNC_OPT', 'A value of c for which the minimum value of f(x) = x² − 4cx + 8c is greater than the maximum value of g(x) = −x² + 3cx − 2c, is', 'mcq', '2', '1/2', '-1/2', '-2', 'b', 'Min of f(x) occurs at x=2c, giving min value −4c²+8c. Max of g(x) occurs at x=3c/2, giving max value 9c²/4−2c. Setting min(f)>max(g) gives 5c²<8c, i.e. 0<c<8/5. Only 1/2 fits this range.', NULL, 7, 'medium', 'medium', 150, 'Confusing which function opens upward vs downward when locating the vertex value.'),
  ('CAT2025_QA_S1_02', 2025, 'Slot 1', 'CAT 2025 Slot 1', TRUE, 'TSD_BASIC', 'Shruti travels 224 km in four parts in 3 hours total. Speeds across the four parts follow an AP, and the times taken follow another AP. She covers the first part at 960 m/min for 30 minutes. The distance, in metres, she travels in the fourth part is', 'mcq', '76800', '112000', '96000', '86400', 'd', 'Times form an AP starting at 30 min summing to 180 min, giving common difference 10 min, so times are 30,40,50,60 min. Speeds also form an AP starting at 960 m/min; using total distance 224000 m, the common difference works out to 160 m/min, so the fourth-part speed is 1440 m/min. Distance = 1440×60 = 86400 m.', NULL, 8, 'high', 'high', 210, 'Forgetting that both speed and time separately follow their own AP, and mixing up which quantity''s common difference to solve for first.'),
  ('CAT2025_QA_S1_03', 2025, 'Slot 1', 'CAT 2025 Slot 1', TRUE, 'NS_FACTORS', 'In a 3-digit number N, the digits are non-zero and distinct such that none of the digits is a perfect square, and only one of the digits is prime. Then, the number of factors of the minimum possible value of N is', 'tita', NULL, NULL, NULL, NULL, '6', 'Digits must avoid {1,4,9} (perfect squares) and 0, leaving {2,3,5,6,7,8}; exactly one digit must be prime (2,3,5,7). To minimise N, put the smallest prime (2) in the hundreds place and the two smallest non-prime digits (6,8) after it: N=268=2²×67, which has (2+1)(1+1)=6 factors.', NULL, 6, 'low', 'medium', 150, 'Forgetting to exclude 0 from the allowed digit pool, or picking a prime digit that isn''t the smallest available.'),
  ('CAT2025_QA_S1_04', 2025, 'Slot 1', 'CAT 2025 Slot 1', TRUE, 'ALG_FUNC_DOMAIN', 'Let 3 ≤ x ≤ 6 and [x²] = [x]², where [x] is the greatest integer not exceeding x. If set S represents all feasible values of x, then a possible subset of S is', 'mcq', '(3,√10) ∪ [5,√26) ∪ {6}', '[3,√10] ∪ [5,√26]', '[3,√10] ∪ [4,√17] ∪ {6}', '(4,√18) ∪ [5,√27) ∪ {6}', 'a', 'On each interval [n,n+1), [x]=n, so [x²]=[x]² forces x² ∈ [n²,n²+1), i.e. x ∈ [n,√(n²+1)). For 3≤x≤6 this gives S=[3,√10) ∪ [4,√17) ∪ [5,√26) ∪ {6}. Option A is the only listed subset consistent with these half-open bounds.', NULL, 8, 'high', 'high', 210, 'Including √10 or similar boundary values as closed endpoints when the interval should be half-open.'),
  ('CAT2025_QA_S1_05', 2025, 'Slot 1', 'CAT 2025 Slot 1', TRUE, 'RATIO_BASIC', 'Stocks A, B and C are priced at Rs 120, 90 and 150 per share respectively. A trader holds 10 shares of A and 20 shares of B and C combined, worth Rs 3300 in total. The number of shares of B she holds is', 'tita', NULL, NULL, NULL, NULL, '15', 'With x shares of B and (20−x) of C: 1200 + 90x + 150(20−x) = 3300, giving 4200−60x=3300, so x=15.', NULL, 4, 'low', 'low', 90, 'Forgetting stock A''s fixed contribution before solving for x.'),
  ('CAT2025_QA_S1_06', 2025, 'Slot 1', 'CAT 2025 Slot 1', TRUE, 'ALG_EXP', 'For any natural number k, let a_k = 3^k. The smallest natural number m for which {(a1)¹×(a2)²×...×(a20)²⁰} < {a21×a22×...×a20+m}, is', 'mcq', '58', '59', '56', '57', 'a', 'LHS = 3^(1² + 2² + ⋯ + 20²) = 3^2870, using n(n+1)(2n+1)/6 = 20(21)(41)/6 = 2870. RHS = 3^(21 + 22 + ⋯ + (20+m)), and that exponent is 20m + m(m+1)/2. The inequality needs 2870 < 20m + m(m+1)/2; doubling gives 5740 < m² + 41m. At m = 57: 3249 + 2337 = 5586, too small. At m = 58: 3364 + 2378 = 5742 > 5740. So the smallest m is 58.', NULL, 8, 'high', 'high', 240, 'Using the sum-of-first-n-naturals formula instead of sum-of-squares for the LHS exponent.'),
  ('CAT2025_QA_S1_07', 2025, 'Slot 1', 'CAT 2025 Slot 1', TRUE, 'ALG_LOG_EQ', 'The number of distinct integers n for which log_(1/4)(n² − 7n + 11) > 0, is', 'mcq', '2', 'infinite', '1', '0', 'd', 'Since the base 1/4 lies in (0,1), log_(1/4)(x)>0 only when 0<x<1. But n²−7n+11 is always an integer for integer n, so it can never lie strictly between 0 and 1. Hence no integer n works.', NULL, 6, 'low', 'medium', 120, 'Forgetting that a log with base between 0 and 1 is positive only for arguments strictly between 0 and 1, not for arguments greater than 1.'),
  ('CAT2025_QA_S1_08', 2025, 'Slot 1', 'CAT 2025 Slot 1', TRUE, 'MOD_COUNT', 'The number of distinct pairs of integers (x, y) satisfying x > y ≥ 3 and x + y < 14 is', 'tita', NULL, NULL, NULL, NULL, '16', 'For y=3, x can be 4..10 (7 values); y=4 gives 5 values; y=5 gives 3 values; y=6 gives 1 value. Total = 7+5+3+1 = 16.', NULL, 5, 'low', 'medium', 120, 'Missing the boundary case x+y<14 (strict inequality) and over/undercounting the last row.'),
  ('CAT2025_QA_S1_09', 2025, 'Slot 1', 'CAT 2025 Slot 1', TRUE, 'CI_HALF', 'At a certain simple rate, a sum amounts to Rs 13920 in 3 years and Rs 18960 in 6.5 years. If instead invested for 2 years at the same rate with interest compounded every 6 months, the total interest earned, in rupees, would be nearest to', 'mcq', '3221', '3180', '3150', '3096', 'a', 'From the two SI conditions, P=9600 and rate=15% p.a. Compounding half-yearly for 2 years at 7.5% per half-year: amount = 9600×(1.075)^4 ≈ 12820.5, giving interest ≈ Rs 3221.', NULL, 7, 'medium', 'medium', 210, 'Using the SI rate directly for annual compounding instead of halving it for half-yearly periods.'),
  ('CAT2025_QA_S1_10', 2025, 'Slot 1', 'CAT 2025 Slot 1', TRUE, 'MIX_REPLACEMENT', 'A container holds 200 litres of a 30% acid solution. 20% is replaced with water, then 10% of the resulting solution is replaced with acid, and finally 15% of that is replaced with water. The final acid percentage is nearest to', 'mcq', '23', '25', '29', '27', 'd', 'Acid after step 1: 60×0.8=48L. After replacing 10% with acid: 48×0.9+20=63.2L. After replacing 15% with water: 63.2×0.85≈53.72L. Percentage = 53.72/200 ≈ 26.86%, nearest to 27.', NULL, 6, 'medium', 'medium', 150, 'Forgetting to add back the pure acid volume when ''replacing with acid'' rather than water.'),
  ('CAT2025_QA_S1_11', 2025, 'Slot 1', 'CAT 2025 Slot 1', TRUE, 'ALG_LINEAR_WORD', 'In a class with more than 10 boys and some girls, after 40% of girls and 60% of boys leave, the remaining girls exceed remaining boys by 8. The minimum possible number of students initially is', 'tita', NULL, NULL, NULL, NULL, '55', '0.6g = 0.4b + 8. Since 0.6g and 0.4b must be integers, both g and b must be multiples of 5. With b>10, the minimum valid pair is b=25, g=30, giving total = 55.', NULL, 6, 'medium', 'medium', 150, 'Not enforcing that both 0.6g and 0.4b must independently be integers.'),
  ('CAT2025_QA_S1_12', 2025, 'Slot 1', 'CAT 2025 Slot 1', TRUE, 'MOD_SELECT', 'A cafeteria offers 5 sandwich types, 4 breads, small/large size, and up to 2 of 6 available sauces (optional). The number of different orders possible is', 'mcq', '880', '840', '800', '600', 'a', 'Sauce choices: C(6,0)+C(6,1)+C(6,2) = 1+6+15 = 22. Total orders = 5 (sandwich) × 4 (bread) × 2 (size) × 22 (sauces) = 880.', NULL, 5, 'low', 'medium', 150, 'Forgetting to include the ''no sauce'' option (C(6,0)=1) when counting up-to-2 selections.'),
  ('CAT2025_QA_S1_13', 2025, 'Slot 1', 'CAT 2025 Slot 1', TRUE, 'ALG_AP', 'In {1,3,5,...,57}, there is k such that the sum of all elements less than k equals the sum of all elements greater than k. Then k equals', 'mcq', '41', '39', '43', '37', 'a', 'The set has 29 terms summing to 29²=841. If k is the m-th odd term, the sum below k is (m−1)² (sum of first m−1 odds). Solving 841−m² = (m−1)² gives m=20, so k = 2(20)+1 = 41.', NULL, 5, 'medium', 'medium', 120, 'Using the wrong formula for the sum of the first m odd numbers, or off-by-one errors in indexing k.'),
  ('CAT2025_QA_S1_14', 2025, 'Slot 1', 'CAT 2025 Slot 1', TRUE, 'TW_WAGES', 'Arun, Varun and Tarun complete a task alone in 24, 21, 15 days, charging Rs 2160, 2400, 2160/day respectively (even for partial days). To finish within 10 days at minimum cost, the minimum amount required is', 'mcq', '38400', '38880', '34400', '47040', 'a', 'Comparing cost-per-full-job (rate×days worked), Tarun is cheapest. Using Tarun alone for 10 days finishes 2/3 of the work; the remaining 1/3 is completed by Varun (next cheapest) in 7 days. Total cost = 10×2160 + 7×2400 = Rs 38400.', NULL, 7, 'high', 'high', 210, 'Assuming the fastest worker is automatically the cheapest, rather than comparing total cost per unit of work.'),
  ('CAT2025_QA_S1_15', 2025, 'Slot 1', 'CAT 2025 Slot 1', TRUE, 'PART_BASIC', 'Kamala invested Rs 100000 in stocks, bonds, and gold, with bond investment = 25% of gold investment. With returns of 10%, 6%, 8% respectively, she gained Rs 8200 total. Her gain from bonds, in rupees, was', 'tita', NULL, NULL, NULL, NULL, '900', 'With B=0.25G, S+B+G=100000, and 0.10S+0.06B+0.08G=8200, solving gives G=60000, B=15000. Gain from bonds = 0.06×15000 = Rs 900.', NULL, 6, 'medium', 'low', 150, 'Not substituting S in terms of B and G correctly before solving the linear system.'),
  ('CAT2025_QA_S1_16', 2025, 'Slot 1', 'CAT 2025 Slot 1', TRUE, 'ALG_LINEAR_2', 'If a − 6b + 6c = 4 and 6a + 3b − 3c = 50, where a, b, c are real numbers, the value of 2a + 3b − 3c is', 'mcq', '20', '14', '18', '15', 'c', 'Multiply the first equation by x and second by y, matching coefficients of a,b,c to the target expression. Solving the resulting system gives x=−4/13, y=5/13, and the target value works out to 18.', NULL, 6, 'medium', 'high', 150, 'Trying to solve for a, b, c individually instead of using a linear combination of the two given equations.'),
  ('CAT2025_QA_S1_17', 2025, 'Slot 1', 'CAT 2025 Slot 1', TRUE, 'GEO_QUAD', 'P(-3,-2), Q(1,-5), R(9,1) are vertices of parallelogram PQRS. The diagonal SQ intersects the x-axis at (a,0). The value of a is', 'mcq', '27/7', '10/3', '13/4', '29/9', 'd', 'S = P + R − Q = (5,4). The line through S(5,4) and Q(1,-5) has slope 9/4; setting y=0 in its equation gives a = 29/9.', NULL, 6, 'medium', 'medium', 150, 'Computing S incorrectly (using the wrong vertex order for the parallelogram diagonal relation).'),
  ('CAT2025_QA_S1_18', 2025, 'Slot 1', 'CAT 2025 Slot 1', TRUE, 'GEO_CIRCLE_CHORD', 'In a circle of radius 6√2 cm centred at C, PQ and SR are parallel chords separated by a diameter, with ∠PQC=45° and the perpendicular distances of PQ, SR from C in ratio 3:2. The area, in sq. cm, of quadrilateral PQRS is', 'mcq', '4(3+√14)', '4(3√2+√7)', '20(3+√14)', '20(3√2+√7)', 'c', 'Triangle PCQ is right-angled and isosceles (45-45-90), giving PQ=12 and AQ=6. Using the 3:2 distance ratio and Pythagoras in triangles ACQ and BCS gives CB=4 and BS=2√14, so RS=4√14. Area = ½×AB×(PQ+RS) = ½×10×(12+4√14) = 20(3+√14).', NULL, 8, 'high', 'high', 240, 'Not recognising triangle PCQ as right-angled from the given 45° angle, which is the key to finding PQ.'),
  ('CAT2025_QA_S1_19', 2025, 'Slot 1', 'CAT 2025 Slot 1', TRUE, 'RATIO_BASIC', 'Morning:afternoon shift ratio was 13:9. After 21 students moved from morning to afternoon, ratio became 19:14. Then new students joined in ratio 3:8, making the final ratio 5:4. The number of new students who joined is', 'mcq', '110', '88', '121', '99', 'd', 'Solving (13k−21)/(9k+21)=19/14 gives k=63, so shifts had 798 and 588 students. With 3t and 8t new joiners, (798+3t)/(588+8t)=5/4 gives t=9, so new students = 11t = 99.', NULL, 6, 'medium', 'high', 180, 'Applying the second ratio condition to the original 13k,9k values instead of the post-shift 798,588 values.'),
  ('CAT2025_QA_S1_20', 2025, 'Slot 1', 'CAT 2025 Slot 1', TRUE, 'GEO_QUAD', 'If a rhombus has side 36 cm and area 396 sq cm, the absolute difference between the lengths of its diagonals, in cm, is', 'tita', NULL, NULL, NULL, NULL, '60', 'Area = d1d2/2 = 396 gives d1d2=792. Also (d1/2)²+(d2/2)²=36² gives d1²+d2²=5184. Then (d1−d2)² = 5184−2(792) = 3600, so |d1−d2| = 60.', NULL, 6, 'medium', 'medium', 150, 'Using the wrong relation between side length and diagonals (forgetting the diagonals bisect at right angles).'),
  ('CAT2025_QA_S1_21', 2025, 'Slot 1', 'CAT 2025 Slot 1', TRUE, 'ALG_QUAD_ROOT', 'The number of non-negative integer values of k for which x² − 5x + k = 0 has only integer roots, is', 'tita', NULL, NULL, NULL, NULL, '3', 'For integer roots, the discriminant 25−4k must be a non-negative perfect square. Checking k=0 (D=25), k=4 (D=9), k=6 (D=1) all work, and no other non-negative k in range gives a perfect square. So there are 3 valid values.', NULL, 6, 'medium', 'medium', 150, 'Stopping after finding one valid k instead of systematically checking all k for which 25-4k stays a perfect square and non-negative.'),
  ('CAT2025_QA_S1_22', 2025, 'Slot 1', 'CAT 2025 Slot 1', TRUE, 'PL_DISHONEST', 'A shopkeeper gives 13 chairs for the discounted price of 12 (discount 22% on marked price) to earn 26% profit on the transaction. If cost price per chair is Rs 100, the marked price, in rupees, is', 'tita', NULL, NULL, NULL, NULL, '175', 'Cost for 13 chairs = 1300; at 26% profit, revenue = 1638, which equals the discounted price of 12 chairs, so discounted SP per chair = 1638/12 = 136.5. Since this is 78% of marked price (22% discount), MP = 136.5/0.78 = 175.', NULL, 6, 'medium', 'high', 150, 'Applying the profit percentage to per-chair cost instead of to the total 13-chair transaction cost.'),
  ('CAT2025_QA_S2_01', 2025, 'Slot 2', 'CAT 2025 Slot 2', TRUE, 'ALG_EXP', 'If 9^(x²+2x−3) − 4(3^(x²+2x−2)) + 27 = 0 then the product of all possible values of x is', 'mcq', '30', '20', '5', '15', 'b', 'Let t=x²+2x−3 and y=3^t. The equation becomes y²−12y+27=0, so y=3 or 9, giving t=1 or 2. Solving x²+2x−4=0 (t=1) has real roots with product −4; solving x²+2x−5=0 (t=2) has real roots with product −5. Overall product = (−4)(−5) = 20.', NULL, 6, 'medium', 'high', 150, 'Forgetting to verify that both resulting quadratics actually have real roots before including their products.'),
  ('CAT2025_QA_S2_02', 2025, 'Slot 2', 'CAT 2025 Slot 2', TRUE, 'MIX_ALLIGATION', 'The average daily book sales is 60 over the first 7 days and 63 over the first 8 days. On day 9, sales are 11 less than day 8, and the average from day 2 to day 9 becomes 66. The sales on day 1 is', 'tita', NULL, NULL, NULL, NULL, '49', 'Sum of days 1-7 = 420, days 1-8 = 504, so day 8 = 84 and day 9 = 73. Sum of days 2-9 = 8×66 = 528 = 504 − d1 + 73, giving d1 = 49.', NULL, 5, 'low', 'medium', 150, 'Mixing up which day''s average corresponds to which partial sum when setting up the equations.'),
  ('CAT2025_QA_S2_03', 2025, 'Slot 2', 'CAT 2025 Slot 2', TRUE, 'ALG_INEQ_MOD', 'The set of all real values of x for which (x² − |x+9| + x) > 0 is', 'mcq', '(-∞,-3) ∪ (3,∞)', '(-∞,-9) ∪ (3,∞)', '(-9,-3) ∪ (3,∞)', '(-∞,-9) ∪ (9,∞)', 'a', 'For x≥-9, |x+9|=x+9 and the inequality reduces to (x-3)(x+3)>0, giving x<-3 or x>3, combined to [-9,-3)∪(3,∞). For x<-9, |x+9|=-x-9 and the inequality becomes x²+2x+9>0, always true, so all x<-9 also work. Combining both cases gives (-∞,-3)∪(3,∞).', NULL, 6, 'medium', 'high', 150, 'Forgetting to check the second case (x<-9) separately since the modulus expression changes sign there.'),
  ('CAT2025_QA_S2_04', 2025, 'Slot 2', 'CAT 2025 Slot 2', TRUE, 'PL_DISCOUNT', 'An item with cost price Rs 1650 is sold at a discount to earn 20% profit. If the discount is doubled, the profit would be Rs 110. The discount rate at which profit% equals discount%, nearest to, is', 'mcq', '16', '18', '14', '12', 'c', 'SP at 20% profit = 1980 = M(1-d); with doubled discount, M(1-2d)=1760. Subtracting gives Md=220, and solving simultaneously gives d=0.1, M=2200. Setting profit% = discount% gives r ≈ 0.1429, i.e. nearest to 14%.', NULL, 7, 'medium', 'high', 210, 'Solving for M and d from the two given scenarios but then not re-solving for a third, different discount rate r.'),
  ('CAT2025_QA_S2_05', 2025, 'Slot 2', 'CAT 2025 Slot 2', TRUE, 'ALG_LINEAR_2', 'If m and n are integers such that (m+2n)(2m+n) = 27, then the maximum possible value of 2m − 3n is', 'tita', NULL, NULL, NULL, NULL, '17', 'Since (m+2n)+(2m+n)=3(m+n), the two factors of 27 used must sum to a multiple of 3, restricting to pairs (3,9),(9,3),(-3,-9),(-9,-3). Solving each pair for integer m,n and evaluating 2m-3n, the maximum value obtained is 17, from (m,n)=(-1,5).', NULL, 7, 'high', 'high', 180, 'Testing all factor pairs of 27 without first filtering by the sum-must-be-multiple-of-3 condition, leading to missed or wasted cases.'),
  ('CAT2025_QA_S2_06', 2025, 'Slot 2', 'CAT 2025 Slot 2', TRUE, 'NS_MISC', 'The sum of digits of the number (625)^65 × (128)^36 is', 'tita', NULL, NULL, NULL, NULL, '25', '625^65 = 5^260 and 128^36 = 2^252, so the product = 2^252 × 5^252 × 5^8 = 10^252 × 5^8. Since 5^8 = 390625, the trailing zeros contribute nothing and the digit sum is 3+9+0+6+2+5 = 25.', NULL, 6, 'medium', 'medium', 150, 'Forgetting to separate out the 10^252 factor (which only appends zeros) before computing the digit sum.'),
  ('CAT2025_QA_S2_07', 2025, 'Slot 2', 'CAT 2025 Slot 2', TRUE, 'ALG_QUAD_ROOT', 'The equations 3x² − 5x + p = 0 and 2x² − 2x + q = 0 have one common root. The sum of the other roots of these equations is', 'mcq', '8/3 - p + 3q/2', '2/3 - p + 3q/2', '8/3 + p + q/3', '2/3 - 2p + 2q/3', 'a', 'With root sums 5/3 and 1 respectively, the sum of the other two roots is 8/3-2r where r is the common root. Eliminating r² between the two given quadratics (using r as the common root) gives r=(2p-3q)/4, and substituting yields 8/3 - p + 3q/2.', NULL, 7, 'high', 'high', 210, 'Errors while eliminating the r² term between the two quadratic equations sharing the common root r.'),
  ('CAT2025_QA_S2_08', 2025, 'Slot 2', 'CAT 2025 Slot 2', TRUE, 'ALG_SPECIAL', 'If log₆₄x² + log₈√y + 3log₅₁₂(√yz) = 4, where x,y,z are positive reals, the minimum possible value of (x+y+z) is', 'mcq', '48', '36', '24', '96', 'a', 'Converting all logs to base 8 using logₐₙb = (1/n)log_a b gives log₈x + log₈√y + log₈(√yz) = 4, i.e. log₈(xyz)=4, so xyz=8⁴=2¹². By AM-GM, (x+y+z)/3 ≥ (xyz)^(1/3) = 16, giving x+y+z ≥ 48.', NULL, 8, 'medium', 'high', 240, 'Not converting all three logarithm bases to a common base before combining the terms.'),
  ('CAT2025_QA_S2_09', 2025, 'Slot 2', 'CAT 2025 Slot 2', TRUE, 'TSD_BOAT', 'Rita and Sneha row at 5 km/h and 6 km/h in still water. In a river with constant current, Sneha takes 48 minutes more to row 14 km upstream than downstream. If Rita starts and returns downstream to the same point, taking 100 minutes total, the total distance, in km, she covers is', 'tita', NULL, NULL, NULL, NULL, '8', 'From Sneha''s data, solving 14/(6-v) - 14/(6+v) = 0.8 gives current speed v=1 km/h. For Rita, upstream speed=4, downstream=6; d/4+d/6=100/60 gives d=4 km, so total distance covered (upstream+downstream) = 2d = 8 km.', NULL, 7, 'high', 'high', 210, 'Using Rita''s speeds to (incorrectly) find the current speed instead of using Sneha''s given time-difference data.'),
  ('CAT2025_QA_S2_10', 2025, 'Slot 2', 'CAT 2025 Slot 2', TRUE, 'NS_MISC', 'Suppose a,b,c are three distinct natural numbers such that 3ac = 8(a+b). The smallest possible value of 3a+2b+c is', 'tita', NULL, NULL, NULL, NULL, '12', 'Since 3ac must be a multiple of 8, ac must be a multiple of 8. Testing a=2,c=4,b=1 satisfies the equation (3×8=8×3=24) and gives 3a+2b+c=12, which is smaller than the a=1,c=8,b=2 case (giving 15).', NULL, 6, 'medium', 'high', 150, 'Only trying the first valid (a,c) pair found instead of checking multiple factorizations of 8 to minimise the target expression.'),
  ('CAT2025_QA_S2_11', 2025, 'Slot 2', 'CAT 2025 Slot 2', TRUE, 'ALG_FUNC_DOMAIN', 'Let f(x)=x/(2x-1) and g(x)=x/(x-1). The domain of h(x)=f(g(x))+g(f(x)) is all real numbers except', 'mcq', '-1, 1/2, and 1', '1/2, 1, and 3/2', '-1/2, 1/2, and 1', '1/2, and 1', 'a', 'f is undefined at x=1/2 and g is undefined at x=1. Simplifying f(g(x))=x/(x+1), which is undefined at x=-1; and g(f(x))=x/(1-x), undefined at x=1 (already excluded). So the domain excludes -1, 1/2, and 1.', NULL, 6, 'medium', 'high', 150, 'Only checking where f and g individually are undefined, without also checking where the composed expressions f(g(x)) and g(f(x)) introduce new undefined points.'),
  ('CAT2025_QA_S2_12', 2025, 'Slot 2', 'CAT 2025 Slot 2', TRUE, 'CI_ANNUAL', 'A loan of Rs 1000 is repaid by two installments of Rs 530 and Rs 594 at the end of year 1 and 2, compounded annually. The rate of interest, in percentage, is', 'mcq', '10', '11', '9', '8', 'd', 'Discounting both installments to present value: 530/(1+r) + 594/(1+r)² = 1000. Substituting x=1/(1+r) gives 594x²+530x-1000=0, solving to x=275/297, which gives r=22/275=8%.', NULL, 7, 'medium', 'high', 210, 'Setting up the present-value equation with the wrong power of (1+r) for one of the two installments.'),
  ('CAT2025_QA_S2_13', 2025, 'Slot 2', 'CAT 2025 Slot 2', TRUE, 'GEO_CIRCLE_TANGENT', 'Two tangents from point P touch a circle with centre O at Q and R. Points A, B lie on PQ, PR such that AB is also tangent to the circle. If ∠AOB=50°, then ∠APB, in degrees, equals', 'tita', NULL, NULL, NULL, NULL, '80', 'By SSS congruence, triangles AOT≅AOQ and BOT≅BOR (T being the point of tangency of AB), giving ∠QOR = 2×∠AOB = 100°. In quadrilateral OQPR, the two angles at Q and R are 90° each (tangent-radius property), so ∠APB = 360° - 90° - 90° - 100° = 80°.', NULL, 7, 'medium', 'high', 210, 'Not recognising the two pairs of congruent triangles formed by the tangent segments, which is needed to relate ∠AOB to ∠QOR.'),
  ('CAT2025_QA_S2_14', 2025, 'Slot 2', 'CAT 2025 Slot 2', TRUE, 'NS_DIVISIBILITY', 'The number of divisors of (2⁶×3⁵×5³×7²) of the form (3r+1), where r is a non-negative integer, is', 'mcq', '36', '56', '24', '42', 'd', 'Any divisor of the form 2^a·3^b·5^c·7^d must have b=0 (else divisible by 3). Since 2≡5≡2 (mod 3) and 7≡1 (mod 3), we need 2^(a+c)≡1 (mod 3), i.e. a+c even. Counting valid (a,c) pairs (0≤a≤6, 0≤c≤3) with even sum gives 14 pairs; with 3 choices for d (0,1,2), total = 14×3 = 42.', NULL, 8, 'high', 'high', 240, 'Forgetting to exclude divisors involving factor 3 (b>0) before checking the mod-3 condition on the remaining factors.'),
  ('CAT2025_QA_S2_15', 2025, 'Slot 2', 'CAT 2025 Slot 2', TRUE, 'GEO_POLY', 'Let ABCDEF be a regular hexagon and P, Q be midpoints of AB and CD respectively. The ratio of areas of trapezium PBCQ to hexagon ABCDEF is', 'mcq', '6:19', '5:24', '6:25', '7:24', 'b', 'With hexagon side a, hexagon area = (3√3/2)a². Trapezium PBCQ has parallel sides BC=a and PQ=1.5a, and height (√3/4)a, giving area = (5√3/16)a². The ratio simplifies to 5:24.', NULL, 7, 'high', 'high', 210, 'Miscalculating the length of PQ (the longer parallel side) by not accounting for the hexagon''s internal geometry correctly.'),
  ('CAT2025_QA_S2_16', 2025, 'Slot 2', 'CAT 2025 Slot 2', TRUE, 'NS_MISC', 'If a,b,c,d are integers with sum 46, the minimum possible value of (a−b)²+(a−c)²+(a−d)² is', 'tita', NULL, NULL, NULL, NULL, '2', 'This is a sum of squared deviations from a, minimised by making all four values as close together as possible. Since 46 isn''t divisible by 4, the closest integer split is 12,11,11,12, giving the expression value (12-11)²+(12-11)²+(12-12)² = 2.', NULL, 5, 'low', 'medium', 120, 'Trying to force all four values exactly equal, which isn''t possible since 46/4 isn''t an integer.'),
  ('CAT2025_QA_S2_17', 2025, 'Slot 2', 'CAT 2025 Slot 2', TRUE, 'RATIO_BASIC', 'The ratio of expenditures of Lakshmi and Meenakshi is 2:3, and Lakshmi''s income to Meenakshi''s expenditure is 6:7. If both save the excess of income over expenditure, and their savings ratio is 4:9, the ratio of their incomes is', 'mcq', '3:5', '5:6', '2:1', '7:8', 'a', 'Let expenditures be B=2k, D=3k. Lakshmi''s income A=(6/7)D=18k/7, so her saving = 4k/7. With Meenakshi''s saving = C-3k, and (4k/7):(C-3k)=4:9, solving gives C=30k/7. Income ratio A:C = 18:30 = 3:5.', NULL, 6, 'medium', 'high', 180, 'Applying the given income-to-expenditure ratio (6:7) to the wrong pair of people''s figures.'),
  ('CAT2025_QA_S2_18', 2025, 'Slot 2', 'CAT 2025 Slot 2', TRUE, 'ALG_GP', 'Let a_n be the nth term of a decreasing infinite GP. If a1+a2+a3=52 and a1a2+a2a3+a3a1=624, the sum of this GP is', 'mcq', '57', '54', '60', '63', 'b', 'From a(1+r+r²)=52 and the second condition simplifying to r/(1+r+r²)=3/13, solving 3r²-10r+3=0 gives r=1/3 or r=3; since the GP is decreasing (|r|<1), r=1/3. Then a=36, and the infinite sum = a/(1-r) = 54.', NULL, 7, 'high', 'high', 210, 'Accepting r=3 as a valid answer without checking the ''decreasing'' and convergence (|r|<1) condition.'),
  ('CAT2025_QA_S2_19', 2025, 'Slot 2', 'CAT 2025 Slot 2', TRUE, 'MIX_ALLIGATION', 'A coffee-cocoa mixture that''s 16% coffee costs Rs 240/kg; one that''s 36% coffee costs Rs 320/kg. If a new mixture costs Rs 376/kg, the quantity, in kg, of coffee in 10 kg of the new mixture is', 'mcq', '5', '4', '2.5', '6', 'a', 'Solving 16C+84K=24000 and 36C+64K=32000 gives C=576, K=176 (coffee, cocoa prices per kg). For the new mixture, 376=p(576)+(1-p)(176) gives p=0.5, i.e. 50% coffee. In 10 kg, coffee = 5 kg.', NULL, 6, 'medium', 'high', 180, 'Solving for the individual coffee/cocoa prices but then misapplying alligation to find the new mixture''s coffee percentage.'),
  ('CAT2025_QA_S2_20', 2025, 'Slot 2', 'CAT 2025 Slot 2', TRUE, 'GEO_TRI_SIM', 'In △ABC, D and E lie on BC and AC. BE and AD meet at T with AD:AT=4:3 and BE:BT=5:4. F lies on AC with DF parallel to BE. Then BD:CD is', 'mcq', '15:4', '11:4', '7:4', '9:4', 'b', 'From AD:AT=4:3, TD:AT=1:3; from BE:BT=5:4, BT:TE=4:1. Using similar triangles ATE~ADF (since DF∥TE) gives DF in terms of TE, and then CFD~CBE (since DF∥BE) gives CD:BC=4:15, leading to BD:CD=11:4.', NULL, 8, 'high', 'high', 240, 'Mixing up which pair of similar triangles to use for the AD segment versus the CD segment ratio.'),
  ('CAT2025_QA_S2_21', 2025, 'Slot 2', 'CAT 2025 Slot 2', TRUE, 'TW_COMBINED', 'Ankita is twice as efficient as Bipin, who is twice as efficient as Chandan. All three start together, Bipin leaves after 20 days, and the job completes in 60 days. The number of days Chandan alone would need is', 'tita', NULL, NULL, NULL, NULL, '340', 'Let Chandan''s rate=x, Bipin=2x, Ankita=4x. First 20 days: combined rate 7x gives 140x done. Remaining 40 days: Ankita+Chandan rate 5x gives 200x done. Total work=340x, which equals 340 days of Chandan''s own rate, so Chandan alone needs 340 days.', NULL, 6, 'medium', 'medium', 150, 'Forgetting that Bipin leaves after day 20, and instead using all three workers for the full 60 days.'),
  ('CAT2025_QA_S2_22', 2025, 'Slot 2', 'CAT 2025 Slot 2', TRUE, 'RATIO_BASIC', 'Money is divided among Pinu, Meena, Rinu and Seema. Pinu gets 20% of the total, Meena gets 40% of the remainder. Seema gets 20% less than Pinu. The ratio of amounts received by Pinu and Rinu is', 'mcq', '2:1', '1:2', '5:8', '8:5', 'c', 'Taking total=100: Pinu=20, remaining=80, Meena=32 (40% of 80), leaving 48 for Rinu and Seema. Seema = 20 - 20%(20) = 16, so Rinu = 48-16 = 32. Ratio Pinu:Rinu = 20:32 = 5:8.', NULL, 5, 'low', 'medium', 120, 'Computing Seema''s share as 20% of the total instead of 20% less than Pinu''s share.'),
  ('CAT2025_QA_S3_01', 2025, 'Slot 3', 'CAT 2025 Slot 3', TRUE, 'PL_SUCCESSIVE_DISCOUNT', 'Monthly sales Jan-Apr were 120,135,150,165 units at cost Rs 240/unit, with fixed marked price. Discounts of 20%,10%,5% applied in Jan,Feb,Mar; none in Apr. Total profit was Rs 138825. The marked price per unit, in rupees, was', 'mcq', '520', '525', '510', '515', 'b', 'Total units=570, total cost=136800. Revenue = 120(0.8X)+135(0.9X)+150(0.95X)+165X = 525X. Profit equation 525X-136800=138825 gives X=525.', NULL, 7, 'medium', 'medium', 210, 'Applying the discount percentages to the wrong months, or forgetting April has no discount.'),
  ('CAT2025_QA_S3_02', 2025, 'Slot 3', 'CAT 2025 Slot 3', TRUE, 'TW_COMBINED', 'Teams A,B,C (5,8,10 equally-productive members) complete a job alone in 40,50,4 hours. 2 from A, 3 from B, 1 from C start the job; the C member leaves after 23 hours. The additional B members needed to finish in the next hour is', 'mcq', '4', '2', '1', '3', 'b', 'Per-member rates: a=W/200, b=W/400, c=W/40. In 23 hours, (2a+3b+c) rate completes 391W/400 of the work, leaving 9W/400. In the next hour, A and B members alone (rate 7W/400) would finish 7W/400, leaving 2W/400, which needs 2 more B-members (each contributing W/400/hour).', NULL, 7, 'high', 'high', 210, 'Not recomputing the group''s combined rate after the team C member leaves before determining how much work remains.'),
  ('CAT2025_QA_S3_03', 2025, 'Slot 3', 'CAT 2025 Slot 3', TRUE, 'ALG_LINEAR_WORD', 'In a school of 1500 students choosing science/arts/commerce with fees Rs 1100/1000/800, total fees collected are Rs 15,50,000. If science students ≤ arts students, the maximum possible number of science students is', 'tita', NULL, NULL, NULL, NULL, '700', 'With S+A+C=1500 and 11S+10A+8C=15500 (after dividing by 100), substituting C=1500-S-A gives 3S+2A=3500. Since S≤A, the maximum feasible S occurs at S=A, giving 5S=3500, so S=700.', NULL, 6, 'medium', 'medium', 180, 'Not recognising that the constraint S≤A becomes binding (S=A) at the maximum, and instead trying to maximise S freely.'),
  ('CAT2025_QA_S3_04', 2025, 'Slot 3', 'CAT 2025 Slot 3', TRUE, 'ALG_AP', 'In an AP, the sum of the 4th, 7th and 10th terms is 99, and the sum of the first 14 terms is 497. The sum of the first five terms is', 'tita', NULL, NULL, NULL, NULL, '65', '3a+18d=99 gives a+6d=33. Also 14/2(2a+13d)=497 gives 2a+13d=71. Solving simultaneously gives a=3, d=5. First five terms: 3,8,13,18,23, summing to 65.', NULL, 6, 'low', 'medium', 150, 'Errors while solving the two simultaneous linear equations in a and d.'),
  ('CAT2025_QA_S3_05', 2025, 'Slot 3', 'CAT 2025 Slot 3', TRUE, 'TSD_BASIC', 'Ankita walks A to C via B and runs back at 40% more than walking speed. She takes exactly 3.5 hours to walk B to C and to run B to A. The total time, in minutes, to walk A to B and run B to C is', 'tita', NULL, NULL, NULL, NULL, '444', 'Walking:running speed ratio = 5:7, so time ratio (for equal distance) = 7:5. Given running B-to-A takes 3.5h, walking A-to-B (same distance, inverse ratio) takes 3.5×7/5=4.9h. Given walking B-to-C takes 3.5h, running B-to-C takes 3.5×5/7=2.5h. Total = 4.9+2.5 = 7.4h = 444 minutes.', NULL, 7, 'high', 'high', 210, 'Applying the speed ratio in the wrong direction when converting between walking-time and running-time for the same distance.'),
  ('CAT2025_QA_S3_06', 2025, 'Slot 3', 'CAT 2025 Slot 3', TRUE, 'NS_MISC', 'For a 4-digit number (>1000), the sum of digits in thousands, hundreds, tens places is 15; sum of digits in hundreds, tens, units is 16; and the tens digit is 6 more than the units digit. The difference between the largest and smallest possible values of the number is', 'mcq', '811', '3289', '735', '4078', 'a', 'Let digits be a,b,c,d. From a+b+c=15 and b+c+d=16, d=a+1. Given c=d+6=a+7, and b=8-2a. Since all digits must be 0-9 and a≥1, only a=1 (giving 1682) and a=2 (giving 2493) are valid. Difference = 2493-1682 = 811.', NULL, 6, 'medium', 'high', 150, 'Not checking that all four derived digit expressions stay within the valid 0-9 range for each candidate value of a.'),
  ('CAT2025_QA_S3_07', 2025, 'Slot 3', 'CAT 2025 Slot 3', TRUE, 'TSD_BASIC', 'Rahul starts at 5 pm at constant speed to reach at 11 pm. He stops 20 minutes, then increases speed by 3 km/h to reach on time. Had he stopped 10 minutes more, he''d need a 5 km/h increase instead. His initial speed, in km/h, was', 'mcq', '12', '15', '18', '20', 'b', 'With total time 6 hours and distance 6x (x=initial speed), setting up two equations for the two stop-duration/speed-increase scenarios and eliminating the unknown stop-point distance gives a linear relation 4x=k (where k involves the stop-point distance); substituting back into either scenario''s equation gives x=15.', NULL, 7, 'high', 'high', 210, 'Not correctly relating the two scenarios'' equations to eliminate the unknown distance travelled before the stop.'),
  ('CAT2025_QA_S3_08', 2025, 'Slot 3', 'CAT 2025 Slot 3', TRUE, 'PIPE_FILL', 'Pipes A, B, C have flow rates in ratio 4:9:36. Pipe A alone fills an empty tank in 15 hours. If all three pipes work together, the time, in minutes, to fill the tank is nearest to', 'mcq', '73', '78', '76', '71', 'a', 'Tank capacity = 15×4x = 60x units. Combined rate = 4x+9x+36x = 49x units/hour. Time = 60x/49x hours ≈ 1.2245 hours ≈ 73.47 minutes, nearest to 73.', NULL, 6, 'low', 'medium', 150, 'Adding the ratio numbers directly as hours instead of converting the ratio to rates relative to pipe A''s known fill time.'),
  ('CAT2025_QA_S3_09', 2025, 'Slot 3', 'CAT 2025 Slot 3', TRUE, 'ALG_HIGHER_DEGREE', 'If f(x) = (x²+3x)(x²+3x+2), the sum of all real roots of √(f(x)+1) = 9701, is', 'mcq', '-6', '6', '3', '-3', 'd', 'Let k=x²+3x. Then f(x)+1 = k(k+2)+1 = (k+1)², so √(f(x)+1) = k+1 = 9701, giving k=9700. The equation x²+3x-9700=0 has a positive discriminant, so real roots exist, with sum = -3 (by Vieta''s).', NULL, 7, 'medium', 'high', 210, 'Not verifying the discriminant of the resulting quadratic is non-negative before assuming real roots exist.'),
  ('CAT2025_QA_S3_10', 2025, 'Slot 3', 'CAT 2025 Slot 3', TRUE, 'ALG_FUNC_DOMAIN', 'For real x, the range of f(x) = (2x-3)/(2x²+4x-6) is', 'mcq', '(-∞,1/8] ∪ [1,∞)', '(-∞,1/4] ∪ [1,∞)', '(-∞,1/8] ∪ [1/2,∞)', '(-∞,1/4] ∪ [1/2,∞)', 'c', 'Setting y=f(x) and cross-multiplying gives a quadratic in x; requiring its discriminant ≥0 (since x is real) leads to 16y²-10y+1≥0, whose roots are y=1/8 and y=1/2. The quadratic in y is negative between these roots, so the range excludes (1/8,1/2), giving (-∞,1/8] ∪ [1/2,∞).', NULL, 8, 'high', 'high', 240, 'Solving the discriminant inequality with a sign error, flipping which region is included versus excluded.'),
  ('CAT2025_QA_S3_11', 2025, 'Slot 3', 'CAT 2025 Slot 3', TRUE, 'NS_MISC', 'The sum of all digits of (10^50 + 10^25 - 123) is', 'mcq', '212', '221', '324', '255', 'b', 'Handle the two parts separately: the number is 10^50 + (10^25 − 123), and since 10^25 − 123 has only 25 digits it does not interact with the leading 1 of 10^50. Now 10^25 − 123 is a 25-digit number ending in 877 with the remaining 22 digits all 9 (check the pattern on a small case: 10³ − 123 = 877). Its digit sum is 22(9) + 8 + 7 + 7 = 198 + 22 = 220. Adding the single leading 1 from 10^50 gives 221.', NULL, 7, 'high', 'high', 210, 'Miscounting how many 9s versus how many 7s and 8s appear in the 10^n-123 digit pattern.'),
  ('CAT2025_QA_S3_12', 2025, 'Slot 3', 'CAT 2025 Slot 3', TRUE, 'GEO_TRI_SPECIAL', 'A triangle ABC has AB=AC=50 cm and BC=80 cm. The sum of the lengths, in cm, of all three altitudes is', 'tita', NULL, NULL, NULL, NULL, '126', 'The altitude from A to BC = 30 cm (by Pythagoras, using half of BC=40). Since altitudes are inversely proportional to their corresponding sides, the ratio of the three altitudes is 1/50:1/50:1/80 = 8:8:5. With the altitude-from-A (ratio 5) equal to 30, the scale factor is 6, giving altitudes 48,48,30, summing to 126.', NULL, 6, 'medium', 'medium', 180, 'Confusing which altitude corresponds to which side when applying the inverse-ratio relationship.'),
  ('CAT2025_QA_S3_13', 2025, 'Slot 3', 'CAT 2025 Slot 3', TRUE, 'ALG_SURDS', 'If (x² + 1/x²) = 25 and x>0, the value of (x⁷ + 1/x⁷) is', 'mcq', '44853√3', '44856√3', '44859√3', '44850√3', 'a', '(x+1/x)² = 27, so x+1/x = 3√3. Cubing gives x³+1/x³ = 72√3. Squaring the original gives x⁴+1/x⁴ = 623. Multiplying (x⁴+1/x⁴)(x³+1/x³) = x⁷+1/x⁷+x+1/x gives x⁷+1/x⁷ = 623×72√3 - 3√3 = 44853√3.', NULL, 8, 'high', 'high', 240, 'Errors in the algebraic identity used to combine x⁴+1/x⁴ and x³+1/x³ into x⁷+1/x⁷.'),
  ('CAT2025_QA_S3_14', 2025, 'Slot 3', 'CAT 2025 Slot 3', TRUE, 'SET_IEP', 'In a class of 150, 75 chose physics, 111 mathematics, 40 chemistry; all chose at least one, at least one chose all three. Physics∩chemistry = chemistry∩maths = half of physics∩maths. The maximum possible number who chose physics but not mathematics is', 'mcq', '30', '35', '40', '55', 'b', 'Setting P∩C=C∩M=k, P∩M=2k, and triple-overlap=x≥1, the total-count equation gives 76=4k-x. To maximise physics-not-maths (=75-2k), minimise k=19+x/4, which is smallest at x=4, giving k=20. So physics-not-maths = 75-40 = 35.', NULL, 8, 'high', 'high', 240, 'Not enforcing the constraint x≥1 (at least one student chose all three), which affects the minimum feasible value of k.'),
  ('CAT2025_QA_S3_15', 2025, 'Slot 3', 'CAT 2025 Slot 3', TRUE, 'ALG_LOG_EQ', 'The sum of all possible real values of x for which log_(x-3)(x²-9) = log_(x-3)(x+1) + 2, is', 'mcq', '-3', '√33', '3', '(3+√33)/2', 'd', 'The base (x-3) must be positive and ≠1, and the argument x²-9 must be positive, so x>3 and x≠4. Rewriting the equation and cross-multiplying gives (x+3)/(x+1) = (x-3), leading to x²-3x-6=0, with roots (3±√33)/2. The negative root is invalid given x>3, leaving only (3+√33)/2.', NULL, 7, 'high', 'high', 210, 'Forgetting the base restrictions (base>0, base≠1) when determining which root of the resulting quadratic is valid.'),
  ('CAT2025_QA_S3_16', 2025, 'Slot 3', 'CAT 2025 Slot 3', TRUE, 'MIX_ALLIGATION', 'The average salary of 5 managers and 25 engineers is Rs 60000. If managers get a 20% raise while engineers'' salary is unchanged, the overall average would rise by 5%. The average salary, in rupees, of engineers is', 'mcq', '45000', '50000', '54000', '40000', 'c', '5x+25y=1800000 (original total). After the raise, 6x+25y=1890000 (5% higher total). Subtracting gives x=90000, and then y=54000.', NULL, 6, 'medium', 'medium', 150, 'Applying the 5% increase to the wrong total (e.g., only to the managers'' portion instead of the combined average).'),
  ('CAT2025_QA_S3_17', 2025, 'Slot 3', 'CAT 2025 Slot 3', TRUE, 'GEO_TRAP', 'ABCD is a trapezium with AB∥DC, AD⊥AB, AB=3DC. A circle inscribed touching all sides has radius 3 cm. The area, in sq cm, of the trapezium is', 'mcq', '48', '30√3', '36√2', '54', 'a', 'Extending BC and AD to meet at E forms similar triangles ABE and DCE. Using the incircle radius formula for the resulting right triangle (r = (s1+s2-hypotenuse)/2) and solving gives DC=x=4. The trapezium area = ½(x+3x)×6 = 12x = 48.', NULL, 8, 'high', 'high', 240, 'Not recognising that extending the non-parallel side and one leg creates similar right triangles, which is key to applying the incircle radius formula.'),
  ('CAT2025_QA_S3_18', 2025, 'Slot 3', 'CAT 2025 Slot 3', TRUE, 'ALG_INDICES', 'If 12^(12x) × 4^(24x+12) × 5^(2y) = 8^(4z) × 20^(12x) × 243^(3x-6), where x,y,z are natural numbers, x+y+z equals', 'tita', NULL, NULL, NULL, NULL, '112', 'Prime-factorising both sides and equating powers of 2, 3, and 5 separately gives three equations: powers of 3 give x=10; powers of 2 give z=42; powers of 5 give y=60. Sum = 10+42+60 = 112.', NULL, 7, 'high', 'high', 210, 'Errors in prime-factorising the composite bases (12, 20, 243) correctly before comparing exponents.'),
  ('CAT2025_QA_S3_19', 2025, 'Slot 3', 'CAT 2025 Slot 3', TRUE, 'GEO_TRI_SIM', 'In △ABC, AB=AC=12 cm and D is on BC with AD=8 cm. AD extended meets E such that ∠ACB=∠AEB. The length, in cm, of AE is', 'mcq', '20', '16', '18', '14', 'c', 'Since AB=AC, ∠ACB=∠ABC=∠ABD. Given ∠ACB=∠AEB, triangles ABE and ADB share ∠BAE=∠DAB and ∠AEB=∠ABD, making them similar (AA). So AB/AD = AE/AB, giving AE = AB²/AD = 144/8 = 18.', NULL, 7, 'medium', 'high', 210, 'Not spotting that ∠ACB equals ∠ABC (isosceles triangle) before linking it to the given ∠AEB condition.'),
  ('CAT2025_QA_S3_20', 2025, 'Slot 3', 'CAT 2025 Slot 3', TRUE, 'MIX_REPLACEMENT', 'Vessels A and B contain 60L alcohol and 60L water. A volume is moved from A to B, then the same volume is moved back from B to A. If the resultant alcohol:water ratio in A is 15:4, the volume initially taken from A, in litres, is', 'tita', NULL, NULL, NULL, NULL, '16', 'With x litres moved out, vessel A''s alcohol after the full exchange = 60-x+x²/(60+x) = 3600/(60+x). Setting this against a total of 60L in the ratio 15:19 (alcohol:total), solving 3600/(60(60+x)) = 15/19 gives x=16.', NULL, 7, 'high', 'high', 210, 'Errors in tracking how much alcohol returns to vessel A during the second (B-to-A) transfer.'),
  ('CAT2025_QA_S3_21', 2025, 'Slot 3', 'CAT 2025 Slot 3', TRUE, 'RATIO_BASIC', 'Boxes A and B had coins in ratio 17:7. After 108 coins moved from A to B, the ratio became 37:20. The number of coins that must be moved further from A to B to make the ratio 1:1 is', 'tita', NULL, NULL, NULL, NULL, '272', 'Let initial counts be 17x, 7x. Solving (17x-108)/(7x+108)=37/20 gives x=76, so counts are 798 and 588 (after using x directly for combined total check). Combined total = 1824, half = 912. Box B currently has 7(76)+108=640, so 912-640=272 more coins must move.', NULL, 6, 'medium', 'high', 180, 'Using the pre-shift ratio (17x,7x) instead of the post-shift totals when calculating how many more coins are needed to equalise.'),
  ('CAT2025_QA_S3_22', 2025, 'Slot 3', 'CAT 2025 Slot 3', TRUE, 'NS_MISC', 'p, q, r are natural numbers with p+q+r=900, r a perfect square between 150 and 500, and 0.3q ≤ p ≤ 0.7q. The sum of the maximum and minimum possible values of p is', 'tita', NULL, NULL, NULL, NULL, '397', 'From 1.3q ≤ 900-r ≤ 1.7q, the minimum p=0.3q occurs when q is minimised (i.e., r is maximised at 484), giving q=320, p=96. The maximum p=0.7q occurs when q is maximised (r minimised at 169), giving q=430, p=301. Sum = 96+301 = 397.', NULL, 7, 'high', 'high', 210, 'Not recognising that minimising p and maximising p require opposite extremes of r (maximum r for minimum p, minimum r for maximum p).'),
  ('CAT2023_QA_S3_01', 2023, 'Slot 3', 'CAT 2023 Official', TRUE, 'ALG_SURDS', 'If x is a positive real number such that x^8 + (1/x)^8 = 47, then the value of x^9 + (1/x)^9 is', 'mcq', '40√5', '30√5', '36√5', '34√5', 'd', 'Repeatedly use (a+1/a)^2 = a^2+1/a^2+2 to step down: x^8+1/x^8=47 gives x^4+1/x^4=7, which gives x^2+1/x^2=3, which gives x+1/x=√5. Then build back up using a^3+1/a^3 identities to get x^3+1/x^3=2√5, and finally x^9+1/x^9=(x^3+1/x^3)^3-3(x^3+1/x^3)=40√5-6√5=34√5.', NULL, 7, 'medium', 'high', 150, 'Trying to solve for x directly instead of working with the symmetric sum x+1/x; sign errors when taking square roots.'),
  ('CAT2023_QA_S3_02', 2023, 'Slot 3', 'CAT 2023 Official', TRUE, 'ALG_INDICES', 'Let n and m be two positive integers such that there are exactly 41 integers greater than 8^m and less than 8^n, which can be expressed as powers of 2. Then, the smallest possible value of n + m is', 'mcq', '42', '44', '14', '16', 'd', '8^m = 2^(3m) and 8^n = 2^(3n). The powers of 2 strictly between them run from 2^(3m+1) to 2^(3n-1), giving (3n-3m-1) terms, which must equal 41, so 3n-3m=42, i.e. n-m=14. With m at its minimum value of 1, n=15, giving m+n=16.', NULL, 6, 'medium', 'medium', 120, 'Forgetting that m must be a positive integer and trying m=0; miscounting the number of integers strictly between two powers.'),
  ('CAT2023_QA_S3_03', 2023, 'Slot 3', 'CAT 2023 Official', TRUE, 'ALG_LINEAR_2', 'For some real numbers a and b, the system of equations x + y = 4 and (a + 5)x + (b^2 − 15)y = 8b has infinitely many solutions for x and y. Then, the maximum possible value of ab is', 'mcq', '33', '25', '15', '55', 'a', 'For infinite solutions the two equations must be proportional: (a+5)/1 = (b^2-15)/1 = 8b/4. From (b^2-15)/1=2b we get b^2-2b-15=0, so b=5 or b=-3. Using a+5=b^2-15 gives a=5 when b=5, and a=-11 when b=-3. The two possible products ab are 25 and 33, so the maximum is 33.', NULL, 6, 'medium', 'medium', 150, 'Forgetting to check both roots of the quadratic in b before picking the maximum product.'),
  ('CAT2023_QA_S3_04', 2023, 'Slot 3', 'CAT 2023 Official', TRUE, 'ALG_LOG', 'For a real number x, if 1/2, log3(2^x−9)/log3 4, and log5(2^x+17/2)/log5 4 are in an arithmetic progression, then the common difference is', 'mcq', 'log4(3/2)', 'log4 7', 'log4(23/2)', 'log4(7/2)', 'd', 'The change-of-base terms simplify to log4(2^x-9) and log4(2^x+17/2). The AP condition gives 2log4(2^x-9) = log4 2 + log4(2^x+17/2), which leads to (2^x-9)^2 = 2(2^x+17/2). Setting t=2^x gives t^2-20t+64=0, so t=4 or t=16; t=4 makes the first log undefined, so t=16. The common difference is log4(2^x-9)-log4 2 = log4 7 - log4 2 = log4(7/2).', NULL, 7, 'high', 'high', 150, 'Not rejecting the extraneous root t=4 that makes a logarithm undefined.'),
  ('CAT2023_QA_S3_05', 2023, 'Slot 3', 'CAT 2023 Official', TRUE, 'ALG_EXP', 'Let n be any natural number such that 5^(n−1) < 3^(n+1). Then, the least integer value of m that satisfies 3^(n+1) < 2^(n+m) for each such n, is', 'tita', NULL, NULL, NULL, NULL, '5', 'Checking small n shows the given inequality 5^(n-1)<3^(n+1) holds for n=1,2,3,4,5 and fails from n=6 onward. For each of these n, find the least integer m so that 3^(n+1)<2^(n+m); the required m must work for the worst case, n=5, which needs m=5.', NULL, 6, 'medium', 'medium', 120, 'Testing only one value of n instead of checking all n for which the first inequality holds.'),
  ('CAT2023_QA_S3_06', 2023, 'Slot 3', 'CAT 2023 Official', TRUE, 'NS_FACTORS', 'The sum of the first two natural numbers, each having 15 factors (including 1 and the number itself), is', 'tita', NULL, NULL, NULL, NULL, '468', 'A number with 15 = 3×5 factors has the form p^2 × q^4 for distinct primes p,q. Using the two smallest primes 2 and 3 in the two possible arrangements gives 2^4×3^2=144 and 2^2×3^4=324, the two smallest such numbers. Their sum is 144+324=468.', NULL, 6, 'medium', 'medium', 120, 'Missing that 15 factors correspond to exponent pattern (2,4) and only considering (14) i.e. a single prime raised to 14.'),
  ('CAT2023_QA_S3_07', 2023, 'Slot 3', 'CAT 2023 Official', TRUE, 'ALG_QUAD_ROOT', 'A quadratic equation x^2 + bx + c = 0 has two real roots. If the difference between the reciprocals of the roots is 1/3, and the sum of the reciprocals of the squares of the roots is 5/9, then the largest possible value of (b + c) is', 'tita', NULL, NULL, NULL, NULL, '9', 'Let the roots be p, q. From 1/p - 1/q = 1/3 and 1/p^2+1/q^2 = 5/9, expanding the second using the first gives (1/(pq))^2 = 1/9, so pq = ±3/2. Since c = pq, taking c = 9/2 (the case giving real roots) and using p+q = pq gives b = -(p+q) with maximum b+c = 9.', NULL, 7, 'high', 'high', 150, 'Sign errors while relating 1/p-1/q and 1/p^2+1/q^2, or forgetting the ± when solving pq.'),
  ('CAT2023_QA_S3_08', 2023, 'Slot 3', 'CAT 2023 Official', TRUE, 'PL_DISHONEST', 'A merchant purchases a cloth at a rate of Rs.100 per meter and receives 5 cm length of cloth free for every 100 cm length of cloth purchased by him. He sells the same cloth at a rate of Rs.110 per meter but cheats his customers by giving 95 cm length of cloth for every 100 cm length of cloth purchased by the customers. If the merchant provides a 5% discount, the resulting profit earned by him is', 'mcq', '4.2%', '9.7%', '15.5%', '16%', 'c', 'Work per centimetre. Buying: he pays Rs 100 and receives 105 cm, so his cost is 100/105 per cm. Selling: the customer pays for 100 cm at Rs 110/m less a 5% discount, i.e. 110 × 0.95 = Rs 104.50, but receives only 95 cm — so the merchant collects 104.50/95 = Rs 1.10 per cm. Profit ratio = 1.10 ÷ (100/105) = 1.10 × 1.05 = 1.155, a profit of 15.5%.', NULL, 6, 'medium', 'medium', 150, 'Not scaling the cost and selling quantities to the same base length (105 cm) before comparing.'),
  ('CAT2023_QA_S3_09', 2023, 'Slot 3', 'CAT 2023 Official', TRUE, 'TW_COMBINED', 'Rahul, Rakshita and Gurmeet, working together, would have taken more than 7 days to finish a job. On the other hand, Rahul and Gurmeet, working together would have taken less than 15 days to finish the job. However, they all worked together for 6 days, followed by Rakshita, who worked alone for 3 more days to finish the job. If Rakshita had worked alone on the job then the number of days she would have taken to finish the job, cannot be', 'mcq', '20', '17', '16', '21', 'd', 'Let daily rates be a, b, c for Rahul, Rakshita, Gurmeet and total work W. The conditions give 7(a+b+c) < W < 15(a+c), and actual completion gives W = 6(a+b+c)+3b. Combining these bounds shows Rakshita''s solo days (W/b) must lie strictly between 15 and 21, ruling out 21.', NULL, 7, 'high', 'high', 180, 'Not converting the ''more than''/''less than'' statements into strict inequalities correctly, or missing that the answer range is open at both ends.'),
  ('CAT2023_QA_S3_10', 2023, 'Slot 3', 'CAT 2023 Official', TRUE, 'PERC_SUCCESSIVE', 'The population of a town in 2020 was 100000. The population decreased by y% from the year 2020 to 2021, and increased by x% from the year 2021 to 2022, where x and y are two natural numbers. If population in 2022 was greater than the population in 2020 and the difference between x and y is 10, then the lowest possible population of the town in 2021 was', 'mcq', '72000', '74000', '73000', '75000', 'c', 'With x=y+10, the 2022 population exceeds the 2020 figure when (100-y)(110+y)>10000. To minimise the 2021 population we maximise y, solving (100-y)(110+y)>10000 as a quadratic gives y<27, so the largest natural number value is y=27, making the 2021 population 100000×0.73 = 73000.', NULL, 7, 'high', 'high', 180, 'Forgetting x and y must be natural numbers, or maximising instead of minimising the right variable.'),
  ('CAT2023_QA_S3_11', 2023, 'Slot 3', 'CAT 2023 Official', TRUE, 'MIX_ALLIGATION', 'Anil mixes cocoa with sugar in the ratio 3 : 2 to prepare mixture A, and coffee with sugar in the ratio 7 : 3 to prepare mixture B. He combines mixtures A and B in the ratio 2 : 3 to make a new mixture C. If he mixes C with an equal amount of milk to make a drink, then the percentage of sugar in this drink will be', 'mcq', '17', '16', '21', '24', 'a', 'Taking 200 ml of A (120 cocoa, 80 sugar) and 300 ml of B (210 coffee, 90 sugar) to get the 2:3 ratio, mixture C has 500 ml total with 170 ml sugar. Diluting with an equal 500 ml of milk gives 1000 ml with 170 ml sugar, i.e. 17%.', NULL, 6, 'medium', 'medium', 150, 'Not using volumes that respect both internal ratios and the 2:3 combining ratio simultaneously.'),
  ('CAT2023_QA_S3_12', 2023, 'Slot 3', 'CAT 2023 Official', TRUE, 'ALG_LINEAR_WORD', 'There are three persons A, B and C in a room. If a person D joins the room, the average weight of the persons in the room reduces by x kg. Instead of D, if person E joins the room, the average weight of the persons in the room increases by 2x kg. If the weight of E is 12 kg more than that of D, then the value of x is', 'mcq', '2', '0.5', '1', '1.5', 'c', 'Let the three original people weigh S in total, so the average is S/3. With D: (S+D)/4 = S/3 − x. With E instead: (S+E)/4 = S/3 + 2x. Subtracting the first from the second cancels S entirely: (E − D)/4 = 3x, so E − D = 12x. Given E − D = 12, we get x = 1.', NULL, 6, 'medium', 'medium', 150, 'Setting up the average equations with the wrong denominator (3 vs 4 people).'),
  ('CAT2023_QA_S3_13', 2023, 'Slot 3', 'CAT 2023 Official', TRUE, 'TSD_BOAT', 'A boat takes 2 hours to travel downstream a river from port A to port B, and 3 hours to return to port A. Another boat takes a total of 6 hours to travel from port B to port A and return to port B. If the speeds of the boats and the river are constant, then the time, in hours, taken by the slower boat to travel from port A to port B is', 'mcq', '12(√5 − 2)', '3(3 + √5)', '3(√5 − 1)', '3(3 − √5)', 'd', 'From the first boat''s times, the river speed works out to d/12 where d is the distance. Setting up the second boat''s total round-trip time as a quadratic in its own speed and solving gives the second boat''s speed; the required one-way time (from A to B, i.e. against the same current direction as before) simplifies to 3(3-√5) hours.', NULL, 7, 'high', 'high', 180, 'Mixing up which direction (upstream/downstream) each travel time corresponds to for the second boat.'),
  ('CAT2023_QA_S3_14', 2023, 'Slot 3', 'CAT 2023 Official', TRUE, 'NS_LCM', 'The number of coins collected per week by two coin-collectors A and B are in the ratio 3 : 4. If the total number of coins collected by A in 5 weeks is a multiple of 7, and the total number of coins collected by B in 3 weeks is a multiple of 24, then the minimum possible number of coins collected by A in one week is', 'tita', NULL, NULL, NULL, NULL, '42', 'Let A collect 3c and B collect 4c coins per week. Then 15c must be a multiple of 7, forcing c to be a multiple of 7, and 12c must be a multiple of 24, forcing c to be a multiple of 2. The smallest such c is lcm(7,2)=14, giving A''s weekly count as 3×14=42.', NULL, 5, 'low', 'medium', 120, 'Not reducing the divisibility conditions on 15c and 12c down to conditions purely on c.'),
  ('CAT2023_QA_S3_15', 2023, 'Slot 3', 'CAT 2023 Official', TRUE, 'PERC_BASIC', 'A fruit seller has a stock of mangoes, bananas and apples with at least one fruit of each type. At the beginning of a day, the number of mangoes make up 40% of his stock. That day, he sells half of the mangoes, 96 bananas and 40% of the apples. At the end of the day, he ends up selling 50% of the fruits. The smallest possible total number of fruits in the stock at the beginning of the day is', 'tita', NULL, NULL, NULL, NULL, '340', 'With total stock S, mangoes = 0.4S, and total sold = 0.2S+96+0.4×(apples) = 0.5S. Expressing S in terms of the apple count a, S=(4a+960)/3, which needs a to be a multiple of 3 for S to be an integer and a multiple of 5 for the apples-sold count to be a whole number. The smallest valid a=15 gives S=340.', NULL, 7, 'high', 'high', 180, 'Not tracking both integer constraints (multiple of 3 and multiple of 5) on the apple count simultaneously.'),
  ('CAT2023_QA_S3_16', 2023, 'Slot 3', 'CAT 2023 Official', TRUE, 'TW_COMBINED', 'Gautam and Suhani, working together, can finish a job in 20 days. If Gautam does only 60% of his usual work on a day, Suhani must do 150% of her usual work on that day to exactly make up for it. Then, the number of days required by the faster worker to complete the job working alone is', 'tita', NULL, NULL, NULL, NULL, '36', 'Let g, s be their daily rates with g+s = W/20. The compensation condition 0.6g+1.5s = g+s simplifies to s/g = 4/5, meaning Gautam is faster. Substituting s=0.8g into the first equation gives g = W/36, so Gautam alone takes 36 days.', NULL, 6, 'medium', 'medium', 150, 'Assuming Suhani (rather than Gautam) is the faster worker without checking the ratio.'),
  ('CAT2023_QA_S3_17', 2023, 'Slot 3', 'CAT 2023 Official', TRUE, 'GEO_TRIG_RATIO', 'Let ABC be an isosceles triangle such that AB and AC are of equal length. AD is the altitude from A on BC and BE is the altitude from B on AC. If AD and BE intersect at O such that ∠AOB = 105°, then AD/BE equals', 'mcq', 'sin 15°', 'cos 15°', '2cos 15°', '2sin 15°', 'c', 'O is the intersection of two altitudes, so it is the orthocentre, and the angle between two altitudes satisfies ∠AOB = 180° − ∠C. From ∠AOB = 105° we get ∠C = 75°, and since AB = AC we also have ∠B = 75° and ∠A = 30°. In right triangle ABD, AD = AB·sin B = AB·sin 75°. In right triangle ABE, BE = AB·sin A = AB·sin 30°. Therefore AD/BE = sin 75°/sin 30° = cos 15° ÷ (1/2) = 2 cos 15°.', NULL, 8, 'high', 'high', 180, 'Not correctly tracking which triangle''s angle sum gives angle C in the cyclic-looking quadrilateral DOEC.'),
  ('CAT2023_QA_S3_18', 2023, 'Slot 3', 'CAT 2023 Official', TRUE, 'GEO_MENS_2D', 'A rectangle with the largest possible area is drawn inside a semicircle of radius 2 cm. Then, the ratio of the lengths of the largest to the smallest side of this rectangle is', 'mcq', '2 : 1', '1 : 1', '√5 : 1', '√2 : 1', 'a', 'With rectangle length l and breadth b, (l/2)^2+b^2 = 2^2 = 4. The area l·b is maximised (by AM-GM) when (l/2)^2 = b^2, i.e. l=2b, giving the ratio l:b = 2:1.', NULL, 6, 'medium', 'medium', 150, 'Not recognising that maximum area under a fixed sum-of-squares constraint occurs when the two squared terms are equal.'),
  ('CAT2023_QA_S3_19', 2023, 'Slot 3', 'CAT 2023 Official', TRUE, 'GEO_POLY', 'In a regular polygon, any interior angle exceeds the exterior angle by 120 degrees. Then, the number of diagonals of this polygon is', 'tita', NULL, NULL, NULL, NULL, '54', 'For an n-sided regular polygon, interior + exterior = 180°, and interior - exterior = 120° gives exterior = 30°, so n = 360/30 = 12. The number of diagonals is 12C2 - 12 = 66-12 = 54.', NULL, 6, 'low', 'low', 120, 'Forgetting to subtract the n sides when computing diagonals from nC2.'),
  ('CAT2023_QA_S3_20', 2023, 'Slot 3', 'CAT 2023 Official', TRUE, 'ALG_SERIES_SPECIAL', 'The value of 1 + (1 + 1/3)(1/4) + (1 + 1/3 + 1/9)(1/16) + (1 + 1/3 + 1/9 + 1/27)(1/64) + ⋯ is', 'mcq', '15/13', '27/12', '15/8', '16/11', 'd', 'Each bracket is a finite GP summing to (3/2)(1-(1/3)^k); rewriting the whole series as a difference of two geometric series in powers of 1/4 and 1/12, and summing both infinite GPs, gives a total of 16/11.', NULL, 8, 'high', 'high', 210, 'Trying to sum the bracket terms without first recognising them as partial sums of the geometric series 1+1/3+1/9+...'),
  ('CAT2023_QA_S3_21', 2023, 'Slot 3', 'CAT 2023 Official', TRUE, 'ALG_AP', 'Let an = 46 + 8n and bn = 98 + 4n be two sequences for natural numbers n ≤ 100. Then, the sum of all terms common to both the sequences is', 'mcq', '14900', '14798', '15000', '14602', 'a', 'The first sequence is 54, 62, 70, …, 846 (terms ≡ 6 mod 8); the second is 102, 106, …, 498 (terms ≡ 2 mod 4). A common term must be ≡ 6 mod 8 and lie in the overlap of the two ranges, [102, 498]. Since 102 ≡ 6 (mod 8), the common terms are 102, 110, …, 494 — the next one, 502, exceeds 498. Count = (494 − 102)/8 + 1 = 50. Sum = 50 × (102 + 494)/2 = 50 × 298 = 14900.', NULL, 7, 'high', 'high', 180, 'Using the wrong common difference for the intersection sequence, or miscounting the number of valid terms within both ranges.'),
  ('CAT2023_QA_S3_22', 2023, 'Slot 3', 'CAT 2023 Official', TRUE, 'ALG_LINEAR_2', 'Suppose f(x, y) is a real-valued function such that f(3x + 2y, 2x - 5y) = 19x, for all real numbers x and y. The value of x for which f(x, 2x) = 27, is', 'tita', NULL, NULL, NULL, NULL, '3', 'Assume f(a,b) = ma+nb; matching coefficients of x and y in m(3x+2y)+n(2x-5y)=19x gives 3m+2n=19 and 2m-5n=0, solving to m=5, n=2, so f(a,b)=5a+2b. Then f(x,2x)=5x+4x=9x=27 gives x=3.', NULL, 6, 'medium', 'medium', 150, 'Not assuming (or verifying) the linear form of f before matching coefficients.'),
  ('CAT2023_QA_S2_01', 2023, 'Slot 2', 'CAT 2023 Official', TRUE, 'ALG_INDICES', 'Let a, b, m and n be natural numbers such that a > 1 and b > 1. If a^m b^n = 144^145, then the largest possible value of n − m is', 'mcq', '580', '290', '289', '579', 'd', '144 = 2⁴ × 3², so 144^145 = 2^580 × 3^290. To split this as a^m · b^n with a, b > 1, one prime power goes to each factor. To maximise n − m, give the larger exponent to n and make m as small as possible: take b = 2 with n = 580, and a = 3^290 with m = 1. Then n − m = 580 − 1 = 579. (The other assignment, b = 3 with n = 290 and a = 2^580 with m = 1, only gives 289.)', NULL, 7, 'medium', 'high', 180, 'Splitting the exponents 580 and 290 incorrectly between a and b, or not minimising m to its smallest valid value of 1.'),
  ('CAT2023_QA_S2_02', 2023, 'Slot 2', 'CAT 2023 Official', TRUE, 'ALG_INEQ_LINEAR', 'Any non-zero real numbers x,y such that y ≠ 3 and x/y < (x+3)/(y−3), will satisfy the condition.', 'mcq', 'x/y < y/x', 'If y < 0, and −x < y', 'If y > 10, and −x > y', 'If x < 0, and −x < y', 'b', 'Rearranging x/y - (x+3)/(y-3) < 0 gives -3(x+y)/[y(y-3)] < 0, i.e. 3(x+y)/[y(y-3)] > 0. If y<0 then y(y-3)>0, forcing x+y>0, i.e. x>0 and |x|>|y|, which means x>y and -x<y.', NULL, 7, 'high', 'high', 180, 'Sign errors while clearing denominators in the inequality, or not testing which answer option is consistent with the derived condition x+y>0.'),
  ('CAT2023_QA_S2_03', 2023, 'Slot 2', 'CAT 2023 Official', TRUE, 'NS_DIVISIBILITY', 'For any natural numbers m, n, and k, such that k divides both m + 2n and 3m + 4n, k must be a common divisor of', 'mcq', 'm and n', '2m and 3n', 'm and 2n', '2m and n', 'c', 'Since k | (m+2n), k also divides 3(m+2n)=3m+6n. Subtracting the given 3m+4n (also divisible by k) leaves 2n divisible by k. Then 2(m+2n)-(2m+4n) type manipulation shows m itself is divisible by k as well, so k divides both m and 2n.', NULL, 6, 'medium', 'medium', 150, 'Only deriving one of the two required divisibility facts and stopping there.'),
  ('CAT2023_QA_S2_04', 2023, 'Slot 2', 'CAT 2023 Official', TRUE, 'ALG_EXP', 'The sum of all possible values of x satisfying the equation 2^(4x^2) − 2^(2x^2+x+16) + 2^(2x+30) = 0, is', 'mcq', '3', '3/2', '5/2', '1/2', 'd', 'Rewriting the equation as (2^(2x^2))^2 - 2·2^(2x^2)·2^(x+15) + (2^(x+15))^2 = 0 shows it''s a perfect square: (2^(2x^2)-2^(x+15))^2=0, so 2x^2=x+15. Solving 2x^2-x-15=0 gives x=3 or x=-5/2, summing to 1/2.', NULL, 7, 'high', 'high', 180, 'Not recognising the expression as a perfect square trinomial in disguise.'),
  ('CAT2023_QA_S2_05', 2023, 'Slot 2', 'CAT 2023 Official', TRUE, 'NS_FACTORS', 'The number of positive integers less than 50, having exactly two distinct factors other than 1 and itself, is', 'tita', NULL, NULL, NULL, NULL, '15', 'A number with exactly 2 factors besides 1 and itself has exactly 4 factors total, meaning it''s either p^3 (a prime cubed) or p×q (product of two distinct primes). Cubes of primes under 50: 8, 27 (2 numbers). Products of two distinct primes under 50: 6,10,14,22,26,34,38,46,58(no),15,21,33,39,35 — filtering correctly under 50 gives 13 such numbers, for a total of 15.', NULL, 6, 'medium', 'medium', 150, 'Forgetting the p^3 case and only counting semiprimes p×q, or missing some semiprime pairs.'),
  ('CAT2023_QA_S2_06', 2023, 'Slot 2', 'CAT 2023 Official', TRUE, 'ALG_LOG_EQ', 'For some positive real number x, if log√3(x) + logx(25)/logx(0.008) = 16/3, then the value of log3(3x^2) is', 'tita', NULL, NULL, NULL, NULL, '7', 'log√3(x) = 2log3(x), and logx(25)/logx(0.008) = log(0.008)(25) = log(5^-3)(5^2) = -2/3. So 2log3(x) - 2/3 = 16/3, giving log3(x)=3, i.e. x^2=3^6. Then log3(3x^2)=log3(3·3^6)=7.', NULL, 7, 'medium', 'medium', 180, 'Mishandling the change-of-base step logx(25)/logx(0.008), which actually equals log(0.008)(25) rather than something requiring x.'),
  ('CAT2023_QA_S2_07', 2023, 'Slot 2', 'CAT 2023 Official', TRUE, 'ALG_INEQ_QUAD', 'Let k be the largest integer such that the equation (x − 1)^2 + 2kx + 11 = 0 has no real roots. If y is a positive real number, then the least possible value of k/(4y) + 9y is', 'tita', NULL, NULL, NULL, NULL, '6', 'Expanding gives x^2-2(k-1)x+12=0; for no real roots the discriminant 4(k-1)^2-48<0, i.e. (k-1)^2<12, giving the largest integer k=4. Then k/(4y)+9y = 1/y+9y, minimised via AM-GM at 2√(9)=6.', NULL, 7, 'high', 'high', 180, 'Not applying AM-GM correctly to 1/y+9y, or picking the wrong boundary integer for k.'),
  ('CAT2023_QA_S2_08', 2023, 'Slot 2', 'CAT 2023 Official', TRUE, 'PIPE_FILL', 'Pipes A and C are fill pipes while Pipe B is a drain pipe of a tank. Pipe B empties the full tank in one hour less than the time taken by Pipe A to fill the empty tank. When pipes A, B and C are turned on together, the empty tank is filled in two hours. If pipes B and C are turned on together when the tank is empty and Pipe B is turned off after one hour, then Pipe C takes another one hour and 15 minutes to fill the remaining tank. If Pipe A can fill the empty tank in less than five hours, then the time taken, in minutes, by Pipe C to fill the empty tank is', 'mcq', '90', '120', '75', '60', 'a', 'Let A take x hours and B take (x-1) hours (draining), C take y hours. From A,B,C together: 1/x - 1/(x-1) + 1/y = 1/2. From the second scenario: 9/(4y) - 1/(x-1) = 1. Solving simultaneously (with x<5) gives y=3/2 hours = 90 minutes.', NULL, 8, 'high', 'high', 210, 'Mixing up which pipe''s rate should be subtracted (drain pipe B) versus added.'),
  ('CAT2023_QA_S2_09', 2023, 'Slot 2', 'CAT 2023 Official', TRUE, 'CI_HALF', 'Anil borrows Rs 2 lakhs at an interest rate of 8% per annum, compounded half-yearly. He repays Rs 10320 at the end of the first year and closes the loan by paying the outstanding amount at the end of the third year. Then, the total interest, in rupees, paid over the three years is nearest to', 'mcq', '45311', '51311', '33130', '40991', 'b', 'Half-yearly compounding at 8% p.a. means 4% per half-year. After one year the debt is 200000 × 1.04² = 216320. He repays 10320, leaving 206000. That balance compounds for two more years — four half-years — to 206000 × 1.04⁴ ≈ 240990.86, which he pays to close the loan. Total outgo = 10320 + 240990.86 = 251310.86, so interest = 251310.86 − 200000 ≈ 51311.', NULL, 7, 'high', 'high', 210, 'Applying annual compounding instead of half-yearly, or forgetting that the repaid amount stops accruing further interest.'),
  ('CAT2023_QA_S2_10', 2023, 'Slot 2', 'CAT 2023 Official', TRUE, 'TSD_RELATIVE', 'Ravi is driving at a speed of 40 km/h on a road. Vijay is 54 meters behind Ravi and driving in the same direction as Ravi. Ashok is driving along the same road from the opposite direction at a speed of 50 km/h and is 225 meters away from Ravi. The speed, in km/h, at which Vijay should drive so that all the three cross each other at the same time, is', 'mcq', '58.8', '67.2', '61.6', '64.4', 'c', 'Ravi and Ashok, closing at 90 km/h (25 m/s) over 225 m, meet in 9 seconds, during which Ravi covers 100 m. Vijay must cover his 54 m gap plus Ravi''s 100 m, i.e. 154 m in 9 seconds, which is 154/9 m/s ≈ 61.6 km/h.', NULL, 7, 'medium', 'high', 210, 'Forgetting to add Ravi''s own distance travelled to Vijay''s required distance.'),
  ('CAT2023_QA_S2_11', 2023, 'Slot 2', 'CAT 2023 Official', TRUE, 'PL_CP_SP', 'Minu purchases a pair of sunglasses at Rs.1000 and sells to Kanu at 20% profit. Then, Kanu sells it back to Minu at 20% loss. Finally, Minu sells the same pair of sunglasses to Tanu. If the total profit made by Minu from all her transactions is Rs.500, then the percentage of profit made by Minu when she sold the pair of sunglasses to Tanu is', 'mcq', '35.42%', '52%', '31.25%', '26%', 'c', 'Minu''s first sale nets Rs.200 profit (selling at Rs.1200). She then buys it back from Kanu for Rs.960 (20% loss on Rs.1200). To reach a total profit of Rs.500, the sale to Tanu must contribute Rs.300 more profit on a cost of Rs.960, i.e. 300/960 = 31.25%.', NULL, 6, 'medium', 'medium', 180, 'Losing track of which transaction''s cost base to use for the final profit percentage.'),
  ('CAT2023_QA_S2_12', 2023, 'Slot 2', 'CAT 2023 Official', TRUE, 'RATIO_DIRECT', 'The price of a precious stone is directly proportional to the square of its weight. Sita has a precious stone weighing 18 units. If she breaks it into four pieces with each piece having distinct integer weight, then the difference between the highest and lowest possible values of the total price of the four pieces will be 288000. Then, the price of the original precious stone is', 'mcq', '1944000', '972000', '1620000', '1296000', 'd', 'With price = k×weight^2 and weights summing to 18, the sum of squares is maximised by making the weights as unequal as possible (e.g. 1,2,3,12) and minimised by making them as close as possible (e.g. 3,4,5,6). The difference between these two sums of squares times k equals 288000, giving k=4000, and the original stone''s price is k×18^2=1296000.', NULL, 7, 'high', 'high', 210, 'Not correctly identifying the extreme weight combinations that maximise/minimise the sum of squares under distinct-integer and fixed-sum constraints.'),
  ('CAT2023_QA_S2_13', 2023, 'Slot 2', 'CAT 2023 Official', TRUE, 'RATIO_BASIC', 'In a company, 20% of the employees work in the manufacturing department. If the total salary obtained by all the manufacturing employees is one-sixth of the total salary obtained by all the employees in the company, then the ratio of the average salary obtained by the manufacturing employees to the average salary obtained by the nonmanufacturing employees is', 'mcq', '6:5', '4:5', '5:4', '5:6', 'b', 'With 100x total employees and 100y total salary, manufacturing has 20x employees earning 100y/6, giving average 5y/6x; non-manufacturing has 80x employees earning 500y/6, giving average 25y/24x. The ratio simplifies to 4:5.', NULL, 6, 'medium', 'medium', 150, 'Applying the one-sixth salary fraction to the wrong group of employees.'),
  ('CAT2023_QA_S2_14', 2023, 'Slot 2', 'CAT 2023 Official', TRUE, 'ALG_INEQ_LINEAR', 'If a certain amount of money is divided equally among n persons, each one receives Rs 352. However, if two persons receive Rs 506 each and the remaining amount is divided equally among the other persons, each of them receive less than or equal to Rs 330. Then, the maximum possible value of n is', 'tita', NULL, NULL, NULL, NULL, '16', 'Total money = 352n. Under the alternate split, the remaining (n-2) persons get (352n-1012)/(n-2) each, which must be ≤ 330. This simplifies to 352+330n ≥ 352n, i.e. n ≤ 352/22 = 16.', NULL, 6, 'medium', 'medium', 150, 'Setting up the remaining-amount expression incorrectly after removing the two Rs.506 shares.'),
  ('CAT2023_QA_S2_15', 2023, 'Slot 2', 'CAT 2023 Official', TRUE, 'PL_CP_SP', 'Jayant bought a certain number of white shirts at the rate of Rs 1000 per piece and a certain number of blue shirts at the rate of Rs 1125 per piece. For each shirt, he then set a fixed market price which was 25% higher than the average cost of all the shirts. He sold all the shirts at a discount of 10% and made a total profit of Rs.51000. If he bought both colors of shirts, then the maximum possible total number of shirts that he could have bought is', 'tita', NULL, NULL, NULL, NULL, '407', 'With m white and n blue shirts, average cost is (1000m+1125n)/(m+n); selling at 1.25× that price with a 10% discount gives a per-shirt profit of (1/8) of the average cost, so total profit = (1/8)(1000m+1125n)=51000, i.e. 1000m+1125n=408000. To maximise m+n, minimise n (keeping n≥1 since both colours were bought); n=8 and m=399 (both integers) gives the maximum total of 407.', NULL, 7, 'high', 'high', 210, 'Not checking that both m and n must be positive integers when searching for the maximum total.'),
  ('CAT2023_QA_S2_16', 2023, 'Slot 2', 'CAT 2023 Official', TRUE, 'MIX_REPLACEMENT', 'A container has 40 liters of milk. Then, 4 liters are removed from the container and replaced with 4 liters of water. This process of replacing 4 liters of the liquid in the container with an equal volume of water is continued repeatedly. The smallest number of times of doing this process, after which the volume of milk in the container becomes less than that of water, is', 'tita', NULL, NULL, NULL, NULL, '7', 'After n replacements, milk volume = 40×(9/10)^n. This falls below 20 (half the total) when (9/10)^n < 1/2, which first happens at n=7.', NULL, 6, 'low', 'medium', 150, 'Using the wrong fraction removed each time (4/40=1/10, so 9/10 remains, not 4/10).'),
  ('CAT2023_QA_S2_17', 2023, 'Slot 2', 'CAT 2023 Official', TRUE, 'GEO_TRIG_RATIO', 'A triangle is drawn with its vertices on the circle C such that one of its sides is a diameter of C and the other two sides have their lengths in the ratio a : b. If the radius of the circle is r, then the area of the triangle is', 'mcq', 'abr^2/[2(a^2+b^2)]', '2abr^2/(a^2+b^2)', '4abr^2/(a^2+b^2)', 'abr^2/(a^2+b^2)', 'b', 'Since one side is the diameter, the angle opposite it is 90°, so the other two sides satisfy (2r)^2 = (ka)^2+(kb)^2 for some scale factor k. The area (1/2)(ka)(kb) can be rewritten using this relation as 2abr^2/(a^2+b^2).', NULL, 7, 'medium', 'high', 180, 'Not using the Thales'' theorem right angle to relate the two legs to the diameter.'),
  ('CAT2023_QA_S2_18', 2023, 'Slot 2', 'CAT 2023 Official', TRUE, 'GEO_TRI_AREA', 'In a rectangle ABCD, AB = 9 cm and BC = 6 cm. P and Q are two points on BC such that the areas of the figures ABP, APQ, and AQCD are in geometric progression. If the area of the figure AQCD is four times the area of triangle ABP, then BP : PQ : QC is', 'mcq', '1:2:4', '1:2:1', '2:4:1', '1:1:2', 'c', 'The rectangle''s area is 9 × 6 = 54. If the three areas are in GP with the third equal to four times the first, then k·r² = 4k ⇒ r = 2, so the areas are k, 2k, 4k and 7k = 54. Triangles ABP and APQ both have height AB = 9 onto bases BP and PQ. Area ABP = (1/2)(BP)(9) = k ⇒ BP = 2k/9, and area APQ = (1/2)(PQ)(9) = 2k ⇒ PQ = 4k/9. With k = 54/7: BP = 12/7 and PQ = 24/7, so QC = 6 − 12/7 − 24/7 = 6/7. Hence BP : PQ : QC = 12 : 24 : 6 = 2 : 4 : 1.', NULL, 7, 'high', 'high', 180, 'Not relating the areas of the sub-triangles sharing the same height from A back to the base segments BP, PQ, QC.'),
  ('CAT2023_QA_S2_19', 2023, 'Slot 2', 'CAT 2023 Official', TRUE, 'GEO_LOCUS', 'The area of the quadrilateral bounded by the Y-axis, the line x = 5, and the lines |x − y| − |x − 5| = 2, is', 'tita', NULL, NULL, NULL, NULL, '45', 'For x ≤ 5, |x-5|=5-x, so the condition becomes |x-y| = 7-x, splitting into two lines y=7 and y=2x-7 (restricted to valid ranges). Plotting these together with the y-axis and x=5 gives a quadrilateral that splits into a rectangle of area 20 and a triangle of area 25, totalling 45.', NULL, 7, 'high', 'high', 210, 'Not splitting the absolute value equation correctly into its two linear cases before sketching the region.'),
  ('CAT2023_QA_S2_20', 2023, 'Slot 2', 'CAT 2023 Official', TRUE, 'ALG_AP', 'Let both the series a1, a2, a3… and b1, b2, b3… be in arithmetic progression such that the common differences of both the series are prime numbers. If a5 = b9, a19 = b19 and b2 = 0, then a11 equals', 'mcq', '86', '79', '83', '84', 'b', 'Subtract a5 = b9 from a19 = b19: the left side gives a19 − a5 = 14d₁ and the right gives b19 − b9 = 10d₂, so 14d₁ = 10d₂, i.e. 7d₁ = 5d₂. Both differences are prime, which forces d₁ = 5 and d₂ = 7. From b2 = 0, b1 = −7, so b9 = −7 + 8(7) = 49. Then a5 = 49 gives a1 + 4(5) = 49, so a1 = 29. Finally a11 = a1 + 10d₁ = 29 + 50 = 79.', NULL, 7, 'high', 'high', 210, 'Not using the prime constraint to pin down the unique common differences from the ratio 5d2=7d1.'),
  ('CAT2023_QA_S2_21', 2023, 'Slot 2', 'CAT 2023 Official', TRUE, 'ALG_SPECIAL', 'If p^2 + q^2 − 29 = 2pq − 20 = 52 − 2pq, then the difference between the maximum and minimum possible value of (p^3 − q^3)', 'mcq', '243', '486', '378', '189', 'c', 'From the two equal expressions, 2pq-20=52-2pq gives pq=18, and p^2+q^2-29=2pq-20 gives p^2+q^2=2pq+9, so (p-q)^2=9, i.e. p-q=±3. Also p^2+q^2=2(18)+9=45, so p^3-q^3=(p-q)(p^2+pq+q^2)=(p-q)(63), giving values ±189; the difference between max and min is 378.', NULL, 8, 'high', 'high', 210, 'Forgetting the ± sign when solving (p-q)^2=9, which halves the apparent range of possible answers.'),
  ('CAT2023_QA_S2_22', 2023, 'Slot 2', 'CAT 2023 Official', TRUE, 'ALG_AP', 'Let an and bn be two sequences such that an = 13 + 6(n − 1) and bn = 15 + 7(n − 1) for all natural numbers n. Then, the largest three digit integer that is common to both these sequences, is', 'tita', NULL, NULL, NULL, NULL, '967', 'Simplifying, an=7+6n and bn=8+7n; both sequences share terms spaced lcm(6,7)=42 apart, starting from the first common value 43. The largest three-digit common term is 43+22×42=967 (checking that the next term would exceed 1000).', NULL, 6, 'medium', 'medium', 150, 'Not verifying the first common term by inspection before building the combined-AP formula.'),
  ('CAT2023_QA_S1_01', 2023, 'Slot 1', 'CAT 2023 Official', TRUE, 'NS_FACTORS', 'Let n be the least positive integer such that 168 is a factor of 1134^n. If m is the least positive integer such that 1134^n is a factor of 168^m, then m + n equals', 'mcq', '9', '15', '12', '24', 'b', '1134 = 2×3^4×7 and 168 = 2^3×3×7. For 168 to divide 1134^n, the factor of 2 (which appears only once per 1134) needs at least 3 copies, so n=3. Then 1134^3 = 2^3×3^12×7^3 must divide 168^m=(2^3×3×7)^m; the bottleneck is the power of 3, needing m≥12. So m+n=15.', NULL, 7, 'medium', 'high', 180, 'Checking only one prime''s exponent requirement instead of finding the binding constraint across all primes.'),
  ('CAT2023_QA_S1_02', 2023, 'Slot 1', 'CAT 2023 Official', TRUE, 'ALG_LOG', 'If x and y are positive real numbers such that logx(x^2 + 12) = 4 and 3 logy x = 1, then x + y equals', 'mcq', '20', '68', '10', '11', 'c', 'From logx(x^2+12)=4, x^2+12=x^4, giving (x^2-4)(x^2+3)=0, so x=2 (positive). From 3logy(x)=1, x=y^(1/3), so y=x^3=8. Then x+y=10.', NULL, 7, 'medium', 'medium', 180, 'Not discarding the extraneous negative root of x^2 from the quartic.'),
  ('CAT2023_QA_S1_03', 2023, 'Slot 1', 'CAT 2023 Official', TRUE, 'ALG_SURDS', 'If √(5x + 9) + √(5x − 9) = 3(2 + √2), then √(10x + 9) is equal to', 'mcq', '3√31', '4√5', '3√7', '2√7', 'c', 'Squaring the RHS gives 3(2+√2) rewritten as √36+√18, matching term by term to 5x+9=36, so x=27/5. Then √(10x+9) = √(54+9) = √63 = 3√7.', NULL, 7, 'medium', 'medium', 180, 'Trying to isolate one square root and square repeatedly instead of matching the RHS to the sum-of-square-roots pattern directly.'),
  ('CAT2023_QA_S1_04', 2023, 'Slot 1', 'CAT 2023 Official', TRUE, 'ALG_SPECIAL', 'If x and y are real numbers such that x^2 + (x − 2y − 1)^2 = −4y(x + y), then the value x − 2y is', 'mcq', '0', '1', '-1', '2', 'b', 'Moving everything to one side and regrouping, the equation becomes (x+2y)^2 + (x-2y-1)^2 = 0. Since both squared terms are non-negative, each must be zero, so x-2y-1=0, giving x-2y=1.', NULL, 7, 'medium', 'high', 180, 'Not recognising the equation as a sum of two perfect squares once fully expanded.'),
  ('CAT2023_QA_S1_05', 2023, 'Slot 1', 'CAT 2023 Official', TRUE, 'ALG_HIGHER_DEGREE', 'The number of integer solutions of equation 2|x|(x^2 + 1) = 5x^2 is', 'tita', NULL, NULL, NULL, NULL, '3', 'x=0 is one solution. For x>0, the equation becomes 2x^3-5x^2+2x=0, factoring to x(2x-1)(x-2)=0, giving the integer solution x=2. For x<0, by symmetry the equation gives x=-2 as the integer solution. In total there are 3 integer solutions: 0, 2, -2.', NULL, 6, 'medium', 'medium', 150, 'Forgetting to separately handle the x=0 case and the sign split from the absolute value.'),
  ('CAT2023_QA_S1_06', 2023, 'Slot 1', 'CAT 2023 Official', TRUE, 'ALG_HIGHER_DEGREE', 'The equation x^3 + (2r + 1)x^2 + (4r − 1)x + 2 = 0 has -2 as one of the roots. If the other two roots are real, then the minimum possible non-negative integer value of r is', 'tita', NULL, NULL, NULL, NULL, '2', 'Dividing the cubic by (x+2) (synthetic division) leaves the quadratic x^2+(2r-1)x+1=0. For this to have two real roots, its discriminant (2r-1)^2-4 must be ≥0, giving r≥3/2 or r≤-1/2; the smallest non-negative integer satisfying this is r=2.', NULL, 7, 'medium', 'high', 180, 'Arithmetic slips while performing the synthetic division to find the coefficients of the quotient quadratic.'),
  ('CAT2023_QA_S1_07', 2023, 'Slot 1', 'CAT 2023 Official', TRUE, 'ALG_QUAD_ROOT', 'Let a and b be the two distinct roots of the equation 2x^2 − 6x + k = 0, such that (a + b) and ab are the distinct roots of the equation x^2 + px + p = 0. Then, the value of 8(k - p) is', 'tita', NULL, NULL, NULL, NULL, '6', 'From the first equation, a+b=3 and ab=k/2. Since (a+b) and ab are roots of x^2+px+p=0, their sum and product give 3+k/2=-p and 3(k/2)=p. Solving these two equations simultaneously gives k=-3/2 and p=-9/4, so 8(k-p)=8(-3/2+9/4)=6.', NULL, 7, 'high', 'high', 180, 'Confusing which pair of numbers (a+b, ab) plays the role of sum/product for the second quadratic.'),
  ('CAT2023_QA_S1_08', 2023, 'Slot 1', 'CAT 2023 Official', TRUE, 'MIX_REPLACEMENT', 'A mixture P is formed by removing a certain amount of coffee from a coffee jar and replacing the same amount with cocoa powder. The same amount is again removed from mixture P and replaced with same amount of cocoa powder to form a new mixture Q. If the ratio of coffee and cocoa in the mixture Q is 16 : 9, then the ratio of cocoa in mixture P to that in mixture Q is', 'mcq', '1 : 3', '1 : 2', '5 : 9', '4 : 9', 'c', 'Taking a total volume of 25 units (16+9), and letting x units be removed/replaced each time, the coffee remaining after two replacements is (25-x)(1-x/25)=16, giving (25-x)^2=400, so x=5. The cocoa in mixture P is x=5 and in mixture Q is 9, giving the ratio 5:9.', NULL, 8, 'high', 'high', 210, 'Applying the replacement formula to only one round instead of two successive rounds of removal-and-replacement.'),
  ('CAT2023_QA_S1_09', 2023, 'Slot 1', 'CAT 2023 Official', TRUE, 'GEO_TRIG_ANGLE', 'The minor angle between the hours hand and minutes hand of a clock was observed at 8:48 am. The minimum duration, in minutes, after 8.48 am when this angle increases by 50% is', 'mcq', '36/11', '2', '4', '24/11', 'd', 'At 8:48, the hour hand is at 264° and the minute hand at 288°, giving a 24° angle. This needs to grow by 12° (50% of 24). The minute hand gains on the hour hand at 5.5°/minute, so the time needed is 12/5.5 = 24/11 minutes.', NULL, 6, 'medium', 'medium', 180, 'Using the wrong relative angular speed (should be 5.5°/min, the minute hand''s rate minus the hour hand''s rate).'),
  ('CAT2023_QA_S1_10', 2023, 'Slot 1', 'CAT 2023 Official', TRUE, 'PL_CP_SP', 'Gita sells two objects A and B at the same price such that she makes a profit of 20% on object A and a loss of 10% on object B. If she increases the selling price such that objects A and B are still sold at an equal price and a profit of 10% is made on object B, then the profit made on object A will be nearest to', 'mcq', '42%', '45%', '47%', '49%', 'c', 'Let the original common selling price be p, so cost of A is 5p/6 and cost of B is 10p/9. The new common selling price giving 10% profit on B is (11/10)(10p/9)=11p/9. The profit percentage on A at this new price is [(11p/9)-(5p/6)]/(5p/6) × 100 ≈ 46.7%, nearest to 47%.', NULL, 7, 'high', 'high', 210, 'Using the original selling price instead of recomputing the new common selling price from B''s profit condition.'),
  ('CAT2023_QA_S1_11', 2023, 'Slot 1', 'CAT 2023 Official', TRUE, 'TSD_AVG', 'Brishti went on an 8-hour trip in a car. Before the trip, the car had travelled a total of x km till then, where x is a whole number and is palindromic, i.e., x remains unchanged when its digits are reversed. At the end of the trip, the car had travelled a total of 26862 km till then, this number again being palindromic. If Brishti never drove at more than 110 km/h, then the greatest possible average speed at which she drove during the trip, in km/h, was', 'mcq', '110', '90', '100', '80', 'c', 'The starting odometer reading is 26862 minus 8 times the average speed, and this reading must also be palindromic (and the speed can''t exceed 110). Testing the answer choices, only speed=100 gives a starting reading of 26062, which is palindromic; 110 gives 25982, not a palindrome.', NULL, 8, 'high', 'high', 210, 'Not checking the palindrome condition on the starting reading for each candidate speed, or assuming the maximum allowed speed (110) automatically works.'),
  ('CAT2023_QA_S1_12', 2023, 'Slot 1', 'CAT 2023 Official', TRUE, 'ALG_INEQ_LINEAR', 'In an examination, the average marks of 4 girls and 6 boys is 24. Each of the girls has the same marks while each of the boys has the same marks. If the marks of any girl is at most double the marks of any boy, but not less than the marks of any boy, then the number of possible distinct integer values of the total marks of 2 girls and 6 boys is', 'mcq', '21', '20', '22', '19', 'a', 'With girl''s marks g and boy''s marks b, 4g+6b=240. The target quantity 2g+6b=240-2g. The constraint b≤g≤2b, combined with 4g+6b=240, restricts g to the range [240/7, 24], so 240-2g ranges over about (171.4, 192], giving 21 distinct integers.', NULL, 7, 'high', 'high', 210, 'Not translating the b≤g≤2b constraint correctly into bounds on g using the total-marks equation.'),
  ('CAT2023_QA_S1_13', 2023, 'Slot 1', 'CAT 2023 Official', TRUE, 'PERC_SUCCESSIVE', 'The salaries of three friends Sita, Gita and Mita are initially in the ratio 5 : 6 : 7, respectively. In the first year, they get salary hikes of 20%, 25% and 20%, respectively. In the second year, Sita and Mita get salary hikes of 40% and 25%, respectively, and the salary of Gita becomes equal to the mean salary of the three friends. The salary hike of Gita in the second year is', 'mcq', '25%', '28%', '26%', '30%', 'c', 'Starting from 5p,6p,7p and applying year-1 hikes gives 6p, 7.5p, 8.4p. In year 2, Sita becomes 8.4p and Mita becomes 10.5p; setting Gita''s new salary g as the mean of all three (3g=8.4p+g+10.5p) gives g=9.45p, a hike of (9.45-7.5)/7.5 = 26% over her year-1 salary.', NULL, 7, 'medium', 'high', 210, 'Computing Gita''s hike against her original (year-0) salary instead of her year-1 salary.'),
  ('CAT2023_QA_S1_14', 2023, 'Slot 1', 'CAT 2023 Official', TRUE, 'TSD_RELATIVE', 'Arvind travels from town A to town B, and Surbhi from town B to town A, both starting at the same time along the same route. After meeting each other, Arvind takes 6 hours to reach town B while Surbhi takes 24 hours to reach town A. If Arvind travelled at a speed of 54 km/h, then the distance, in km, between town A and town B is', 'tita', NULL, NULL, NULL, NULL, '972', 'Using the classic meeting-point relation, the time to meet t satisfies t^2 = 6×24 = 144, so t=12. Surbhi''s speed then follows from s×12=54×6, giving s=27. The total distance is (54+27)×12=972 km.', NULL, 6, 'low', 'medium', 150, 'Not knowing/applying the standard identity t^2 = (time for A after meeting)×(time for B after meeting).'),
  ('CAT2023_QA_S1_15', 2023, 'Slot 1', 'CAT 2023 Official', TRUE, 'CI_HALF', 'Anil invests Rs. 22000 for 6 years in a certain scheme with 4% interest per annum, compounded half-yearly. Sunil invests in the same scheme for 5 years, and then reinvests the entire amount received at the end of 5 years for one year at 10% simple interest. If the amounts received by both at the end of 6 years are same, then the initial investment made by Sunil, in rupees, is', 'tita', NULL, NULL, NULL, NULL, '20808', 'Anil''s maturity value is 22000×(1.02)^12. Sunil''s is S×(1.02)^10×1.1. Equating the two and simplifying, S = 22000×(1.02)^2/1.1 = 20808.', NULL, 7, 'medium', 'medium', 210, 'Applying the half-yearly rate incorrectly to the final simple-interest year, or mismatching the number of compounding periods.'),
  ('CAT2023_QA_S1_16', 2023, 'Slot 1', 'CAT 2023 Official', TRUE, 'TW_COMBINED', 'The amount of job that Amal, Sunil and Kamal can individually do in a day, are in harmonic progression. Kamal takes twice as much time as Amal to do the same amount of job. If Amal and Sunil work for 4 days and 9 days, respectively, Kamal needs to work for 16 days to finish the remaining job. Then the number of days Sunil will take to finish the job working alone, is', 'tita', NULL, NULL, NULL, NULL, '27', 'Let the daily rates be a, s, k. Rates in HP means 2/s = 1/a + 1/k. Kamal takes twice as long as Amal, so his rate is half: k = a/2. Substituting, 2/s = 1/a + 2/a = 3/a, hence a = 3s/2 and k = 3s/4. The job is W = 4a + 9s + 16k = 4(3s/2) + 9s + 16(3s/4) = 6s + 9s + 12s = 27s. Sunil alone needs W/s = 27 days.', NULL, 8, 'high', 'high', 210, 'Mixing up whether ''takes twice as much time'' means twice the rate or half the rate.'),
  ('CAT2023_QA_S1_23', 2023, 'Slot 1', 'CAT 2023 Official', TRUE, 'GEO_COORD_CIRCLE', 'Let C be the circle x^2 + y^2 + 4x − 6y − 3 = 0 and L be the locus of the point of intersection of a pair of tangents to C with the angle between the two tangents equal to 60°. Then, the point at which L touches the line x = 6 is', 'mcq', '(6, 6)', '(6, 3)', '(6, 8)', '(6, 4)', 'b', 'The circle has centre (-2,3) and radius 4. For tangents from an external point subtending 60° between them, the distance from that point to the centre satisfies sin(30°)=radius/distance, giving distance=8. Setting the point as (h,k) with (h+2)^2+(k-3)^2=64 and h=6 gives k=3.', NULL, 7, 'high', 'high', 210, 'Using the wrong half-angle (30° instead of using the full 60° directly) when relating the tangent-pair angle to the distance from the centre.'),
  ('CAT2023_QA_S1_18', 2023, 'Slot 1', 'CAT 2023 Official', TRUE, 'GEO_CYCLIC', 'A quadrilateral ABCD is inscribed in a circle such that AB : CD = 2 : 1 and BC : AD = 5 : 4. If AC and BD intersect at the point E, then AE : CE equals', 'mcq', '2 : 1', '1 : 2', '8 : 5', '5 : 8', 'c', 'Using the inscribed-angle equalities, triangles AED and BEC are similar (giving AE/BE = AD/BC = 4/5), and triangles AEB and DEC are similar (giving BE/CE = AB/CD = 2/1). Multiplying these two ratios gives AE/CE = 8/5.', NULL, 7, 'high', 'high', 210, 'Using only one pair of similar triangles instead of combining both to eliminate BE.'),
  ('CAT2023_QA_S1_19', 2023, 'Slot 1', 'CAT 2023 Official', TRUE, 'GEO_TRI_AREA', 'In a right-angled triangle ΔABC, the altitude AB is 5 cm, and the base BC is 12 cm. P and Q are two points on BC such that the areas of △ABP, △ABQ and △ABC are in arithmetic progression. If the area of ΔABC is 1.5 times the area of △ABP, the length of PQ, in cm, is', 'tita', NULL, NULL, NULL, NULL, '2', 'Area of ABC = 30, so area of ABP = 30/1.5 = 20, giving BP=8 (since area=2.5×BP). The AP condition 2×(area ABQ) = area ABP + area ABC gives area ABQ=25, so BQ=10. PQ = BQ-BP = 2.', NULL, 6, 'medium', 'medium', 180, 'Not converting the area conditions into base-length conditions using the common height AB=5.'),
  ('CAT2023_QA_S1_20', 2023, 'Slot 1', 'CAT 2023 Official', TRUE, 'ALG_AP', 'For some positive and distinct real numbers x, y and z, if 1/(√y+√z) is the arithmetic mean of 1/(√x+√z) and 1/(√x+√y), then the relationship which will always hold true, is', 'mcq', '√x, √z and √y are in arithmetic progression', 'y, x and z are in arithmetic progression', 'x, y and z are in arithmetic progression', '√x, √y and √z are in arithmetic progression', 'b', 'Cross-multiplying the arithmetic-mean condition and expanding both sides, the surd terms cancel out, leaving the clean relation 2x=y+z, meaning y, x, z are in arithmetic progression.', NULL, 7, 'high', 'high', 210, 'Getting lost in the surd algebra and not noticing the cross terms cancel to leave a simple linear relation.'),
  ('CAT2023_QA_S1_21', 2023, 'Slot 1', 'CAT 2023 Official', TRUE, 'MOD_COUNT', 'The number of all natural numbers up to 1000 with non-repeating digits is', 'mcq', '504', '648', '738', '585', 'c', '1-digit numbers: 9. 2-digit numbers: 9 choices for the first digit times 9 for the second (excluding the first) = 81. 3-digit numbers: 9×9×8 = 648. Adding 1000 itself (repeated digits, so excluded) gives a total of 9+81+648 = 738.', NULL, 6, 'medium', 'medium', 180, 'Forgetting to exclude 0 as a leading digit while still allowing it in other positions.'),
  ('CAT2023_QA_S1_22', 2023, 'Slot 1', 'CAT 2023 Official', TRUE, 'ALG_RECURRENCE', 'A lab experiment measures the number of organisms at 8 am every day. Starting with 2 organisms on the first day, the number of organisms on any day is equal to 3 more than twice the number on the previous day. If the number of organisms on the nth day exceeds one million, then the lowest possible value of n is', 'tita', NULL, NULL, NULL, NULL, '19', 'Solving the recurrence T(n)=2T(n-1)+3 gives the closed form T(n)=2^n+3(2^(n-1)-1). Testing n=18 gives a value just under 2^19, still below one million-scale growth needed; testing n=19 gives a value exceeding one million, while n=18 does not, so the answer is 19.', NULL, 8, 'high', 'high', 210, 'Not solving the recurrence in closed form and instead trying to compute many terms by hand, risking arithmetic errors.'),
  ('CAT2022_QA_S3_01', 2022, 'Slot 3', 'CAT 2022 Slot 3', TRUE, 'ALG_SPECIAL', 'If c = 16x/y + 49y/x for some non-zero real numbers x and y, then c cannot take the value', 'mcq', '60', '-50', '-70', '-60', 'b', 'Let t = x/y. Then c = 16t + 49/t. By AM-GM, |16t+49/t| >= 2*sqrt(16*49) = 56, so c is in (-inf,-56] U [56,inf). Since -50 lies outside this range, c cannot equal -50.', NULL, 6, 'medium', 'medium', 150, 'Forgetting AM-GM only bounds the absolute value, so checking each option against |c|>=56 rather than just c>=56.')
) AS v (
  external_id, year, slot, source, is_pyq,
  concept_code,
  question_text, question_type,
  option_a, option_b, option_c, option_d,
  correct_answer, solution, alternate_solution,
  difficulty, calculation_level, logic_level,
  expected_time_seconds, common_mistakes
)
JOIN subtopics s ON s.concept_code = v.concept_code
ON CONFLICT (exam_id, external_id) DO NOTHING;
